app/lib/ai.server.ts.source:
// What AI sessions may do beyond what the buttons do, and the rules around it (design decision 2 and
// section 5, "MCP tools"). The writes still go through content.server.ts, the same functions as the
// buttons, so every role rule applies unchanged; this adds the AI-only rules on top:
//
// - an AI session is an AI client acting for a person, known by the door it came through;
// - a reviewer (another company's agent) reads and flags, and never writes text or publishes;
// - an AI draft is saved beside the person's own draft, never over it or to the site;
// - publish is the Owner's own sessions only, refused while any flag on the item is open, recorded
//   as "published by <client> on Dustin's instruction", and emailed to Dustin with an unpublish link.

import { and, asc, desc, eq, sql } from "drizzle-orm";
import { drizzle } from "drizzle-orm/d1";

import { aiDrafts, aiPublications, findings, siteItems } from "~/db/schema";
import { readDoc, writeToSite, type ProjectRole, type WriteOutcome } from "~/lib/content.server";
import type { Viewer } from "~/lib/people.server";
import type { SiteProject } from "~/lib/projects.server";
import { can } from "~/lib/roles";
import { siteEntry } from "~/lib/sites.server";
import { draftForEvent, draftSocialPost } from "~/lib/social/queue.server";

/**
 * An AI client acting for a person, known by the door it came through: the person the OAuth grant
 * belongs to, and the client that holds the grant (its CIMD name), credited on every change.
 */
export type AiSession = { viewer: Viewer; client: string };

/** A refusal an AI tool reports back to the client as its answer, never a crash. */
export class AiRefusal extends Error {
  constructor(message: string) {
    super(message);
    this.name = "AiRefusal";
  }
}

// ---------- flags on an item

export type ItemFinding = {
  id: number;
  check: string;
  message: string;
  excerpt: string | null;
  status: "open" | "dismissed";
  createdAt: string;
};

export async function itemFindings(db: D1Database, project: ProjectRole, itemId: string): Promise<ItemFinding[]> {
  if (!can(project.role, "read")) throw new Response("Forbidden", { status: 403 });
  return drizzle(db)
    .select({
      id: findings.id,
      check: findings.checkName,
      message: findings.message,
      excerpt: findings.excerpt,
      status: findings.status,
      createdAt: findings.createdAt,
    })
    .from(findings)
    .where(and(eq(findings.projectId, project.id), eq(findings.path, itemId)))
    .orderBy(desc(findings.createdAt), desc(findings.id))
    .all();
}

async function fingerprint(parts: (string | null)[]): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(JSON.stringify(parts)));
  return [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

/**
 * A flag from an AI session, a reviewer's above all (design B6: reviewers write findings, never
 * text). Anyone who may comment may flag. The same flag twice is one flag.
 */
export async function addFinding(
  db: D1Database,
  project: ProjectRole,
  session: AiSession,
  itemId: string,
  input: { message: string; excerpt?: string | null },
): Promise<{ id: number; duplicate: boolean }> {
  if (!can(project.role, "comment")) throw new AiRefusal("You may not flag anything on this project.");
  const message = input.message.trim();
  if (!message || message.length > 2000) throw new AiRefusal("A flag needs a message of up to 2,000 characters.");
  const excerpt = input.excerpt?.trim() || null;
  const check = session.viewer.isReviewer ? "review" : "ai";
  const full = `${message} (from ${session.client})`;
  const key = await fingerprint([check, full, excerpt]);
  const d = drizzle(db);
  const inserted = await d
    .insert(findings)
    .values({ projectId: project.id, path: itemId, checkName: check, message: full, excerpt, fingerprint: key })
    .onConflictDoNothing()
    .returning({ id: findings.id });
  if (inserted[0]) return { id: inserted[0].id, duplicate: false };
  const existing = await d
    .select({ id: findings.id })
    .from(findings)
    .where(and(eq(findings.projectId, project.id), eq(findings.path, itemId), eq(findings.fingerprint, key)))
    .get();
  return { id: existing!.id, duplicate: true };
}

export type ProjectFlag = ItemFinding & { itemId: string; title: string | null; onSite: boolean };

/**
 * Every flag on a site project, open first then newest first, including flags on items the site does
 * not have (a proof item, a post since deleted), which no editor page can reach. `onSite` says whether
 * Carrel's index of the site has the item.
 */
export async function projectFlags(db: D1Database, project: ProjectRole): Promise<ProjectFlag[]> {
  if (!can(project.role, "read")) throw new Response("Forbidden", { status: 403 });
  const rows = await drizzle(db)
    .select({
      id: findings.id,
      itemId: findings.path,
      check: findings.checkName,
      message: findings.message,
      excerpt: findings.excerpt,
      status: findings.status,
      createdAt: findings.createdAt,
      title: siteItems.title,
    })
    .from(findings)
    .leftJoin(siteItems, and(eq(siteItems.projectId, findings.projectId), eq(siteItems.itemId, findings.path)))
    .where(eq(findings.projectId, project.id))
    .orderBy(asc(sql`${findings.status} = 'dismissed'`), desc(findings.createdAt), desc(findings.id))
    .all();
  return rows.map((r) => ({ ...r, onSite: r.title !== null }));
}

/** Checks and reviewers flag; a person decides. Dismissing clears a flag for publish, so it is the Owner's. */
export async function dismissItemFinding(db: D1Database, project: ProjectRole, viewer: Viewer, itemId: string, id: number, now = new Date()) {
  if (!can(project.role, "publish")) throw new Response("Forbidden", { status: 403 });
  const result = await drizzle(db)
    .update(findings)
    .set({ status: "dismissed", dismissedBy: viewer.id, dismissedAt: now.toISOString() })
    .where(and(eq(findings.id, id), eq(findings.projectId, project.id), eq(findings.path, itemId)))
    .returning({ id: findings.id });
  if (result.length === 0) throw new Response("Not found", { status: 404 });
}

// ---------- AI drafts, beside the person's own

export async function saveAiDraft(
  env: Env,
  project: SiteProject,
  session: AiSession,
  itemId: string,
  input: { source: string; note?: string },
  fetcher?: typeof fetch,
): Promise<{ id: number; baseVersion: string | null }> {
  if (session.viewer.isReviewer) throw new AiRefusal("A reviewer flags; it does not write text. Use add_finding.");
  if (!can(project.role, "edit")) throw new AiRefusal("You may not write drafts on this project.");
  if (!input.source.trim()) throw new AiRefusal("The draft is empty.");
  let baseVersion: string | null = null;
  try {
    baseVersion = (await readDoc(env, project, itemId, fetcher))?.version ?? null;
  } catch {
    // The site not answering does not stop a draft that lives only in Carrel.
  }
  const [row] = await drizzle(env.DB)
    .insert(aiDrafts)
    .values({
      projectId: project.id,
      itemId,
      personId: session.viewer.id,
      client: session.client,
      source: input.source.replace(/\r\n/g, "\n"),
      baseVersion,
      note: (input.note ?? "").trim().slice(0, 500),
    })
    .returning({ id: aiDrafts.id });
  return { id: row!.id, baseVersion };
}

export type AiDraftSummary = { id: number; client: string; note: string; createdAt: string; baseVersion: string | null; words: number };

/** The AI drafts a person's own sessions saved for this item, newest first. Private to the person, as drafts are. */
export async function listAiDrafts(db: D1Database, project: ProjectRole, viewer: Viewer, itemId: string): Promise<AiDraftSummary[]> {
  if (!can(project.role, "read")) throw new Response("Forbidden", { status: 403 });
  const rows = await drizzle(db)
    .select({ id: aiDrafts.id, client: aiDrafts.client, note: aiDrafts.note, createdAt: aiDrafts.createdAt, baseVersion: aiDrafts.baseVersion, source: aiDrafts.source })
    .from(aiDrafts)
    .where(and(eq(aiDrafts.projectId, project.id), eq(aiDrafts.itemId, itemId), eq(aiDrafts.personId, viewer.id)))
    .orderBy(desc(aiDrafts.createdAt), desc(aiDrafts.id))
    .all();
  return rows.map(({ source, ...r }) => ({ ...r, words: source.split(/\s+/).filter(Boolean).length }));
}

export async function readAiDraft(db: D1Database, project: ProjectRole, viewer: Viewer, itemId: string, id: number) {
  if (!can(project.role, "read")) throw new Response("Forbidden", { status: 403 });
  const row = await drizzle(db)
    .select()
    .from(aiDrafts)
    .where(and(eq(aiDrafts.id, id), eq(aiDrafts.projectId, project.id), eq(aiDrafts.itemId, itemId), eq(aiDrafts.personId, viewer.id)))
    .get();
  if (!row) throw new Response("Not found", { status: 404 });
  return row;
}

// ---------- publish by instruction

export type AiPublishResult = { ok: true; version: string; changeId: string; emailed: boolean } | { ok: false; message: string };

/** The line the record, the email and the editor all use (decision 2c). */
export function publishedByLine(client: string): string {
  return `Published by ${client} on Dustin's instruction.`;
}

/**
 * Publishes the item as it stands on the site at `expectedVersion`: no text travels with it, so an
 * AI can only publish what a person saved. Every refusal comes before the site is asked anything.
 */
export async function aiPublish(
  env: Env,
  project: SiteProject,
  session: AiSession,
  itemId: string,
  expectedVersion: string,
  opts: { fetcher?: typeof fetch; carrelOrigin: string },
): Promise<AiPublishResult> {
  if (session.viewer.isReviewer) throw new AiRefusal("A reviewer never publishes.");
  // Owner only, whatever a shared person's role: decision 2a gives publish to Dustin's sessions alone.
  if (!session.viewer.isOwner || project.role !== "owner") throw new AiRefusal("Only the Owner's own sessions may publish.");
  const open = (await itemFindings(env.DB, project, itemId)).filter((f) => f.status === "open");
  if (open.length > 0) {
    throw new AiRefusal(
      `Publish is refused while ${open.length} flag${open.length === 1 ? " is" : "s are"} open on this post: ${open
        .map((f) => f.message)
        .join(" | ")} Dustin fixes the text or dismisses each flag in Carrel first.`,
    );
  }

  const outcome: WriteOutcome = await writeToSite(env, project, session.viewer, itemId, { action: "publish", expectedVersion }, opts.fetcher, {
    client: session.client,
  });
  if (!outcome.ok) return { ok: false, message: outcome.message };

  const d = drizzle(env.DB);
  await d.insert(aiPublications).values({
    changeId: outcome.changeId,
    projectId: project.id,
    itemId,
    personId: session.viewer.id,
    client: session.client,
    version: outcome.version,
  });

  // The email goes out now; if it cannot, the record keeps the error and the health check reports it.
  let emailed = false;
  try {
    const doc = await readDoc(env, project, itemId, opts.fetcher).catch(() => null);
    const title = doc?.title || itemId;
    const unpublish = `${opts.carrelOrigin}/p/${encodeURIComponent(project.slug)}/e/${encodeURIComponent(itemId)}/unpublish`;
    await env.EMAIL.send({
      from: env.ALERT_FROM,
      to: env.ALERT_EMAIL,
      subject: `Carrel: ${session.client} published "${title}"`,
      text: [
        publishedByLine(session.client),
        "",
        `${title} on ${siteEntry(project.site).name}${doc?.path ? `: ${doc.path}` : ""}`,
        `Version ${outcome.version}, change ${outcome.changeId}.`,
        "",
        `Unpublish it: ${unpublish}`,
        "",
      ].join("\n"),
    });
    emailed = true;
    await d.update(aiPublications).set({ emailedAt: new Date().toISOString() }).where(eq(aiPublications.changeId, outcome.changeId));
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    console.error(JSON.stringify({ aiPublish: "email-failed", changeId: outcome.changeId, error: message }));
    await d.update(aiPublications).set({ emailError: message }).where(eq(aiPublications.changeId, outcome.changeId));
  }
  return { ok: true, version: outcome.version, changeId: outcome.changeId, emailed };
}

/** The last AI publish of an item, for the editor to show who published it. */
export async function lastAiPublication(db: D1Database, project: SiteProject, itemId: string) {
  return (
    (await drizzle(db)
      .select({ client: aiPublications.client, publishedAt: aiPublications.publishedAt, emailedAt: aiPublications.emailedAt })
      .from(aiPublications)
      .where(and(eq(aiPublications.projectId, project.id), eq(aiPublications.itemId, itemId)))
      .orderBy(desc(aiPublications.publishedAt))
      .get()) ?? null
  );
}

// ---------- social posts, drafted by the session that finished the piece (decision 5)

/**
 * Stores an AI session's drafted social post for the queue, by the event id the routine was given or
 * by account and item. Social posts are Dustin's alone, so only his own sessions may draft them.
 */
export async function aiDraftSocialPost(
  db: D1Database,
  session: AiSession,
  input: { eventId: number; text: string } | { accountKey: string; projectId: number; itemId: string; text: string },
): Promise<{ postId: number }> {
  if (session.viewer.isReviewer || !session.viewer.isOwner) throw new AiRefusal("Social posts are Dustin's: only his own sessions may draft them.");
  const result =
    "eventId" in input
      ? await draftForEvent(db, { eventId: input.eventId, text: input.text, createdBy: session.client })
      : await draftSocialPost(db, { ...input, createdBy: session.client });
  if (!result.ok) throw new AiRefusal(result.error);
  return { postId: result.postId };
}

app/lib/history.server.ts.source:
// What a site remembers about one item: its revisions, the source at each, and the patch between
// two. Read-only: nothing here writes to the site or to Carrel. A Reader may read all of it, so the
// check is "read", and it sits here so every door asks the same question.

import type { Revision } from "@dustinedwards/site-api";
import { SiteApiError } from "@dustinedwards/site-api/client";

import type { SiteProject } from "~/lib/projects.server";
import { can } from "~/lib/roles";
import { siteClient } from "~/lib/sites.server";

function requireRead(project: { role: SiteProject["role"] }) {
  if (!can(project.role, "read")) throw new Response("Forbidden", { status: 403 });
}

/** A 404 from the site means it does not hold that item or version; every other failure is the caller's to show. */
async function orNull<T>(run: () => Promise<T>): Promise<T | null> {
  try {
    return await run();
  } catch (error) {
    if (error instanceof SiteApiError && error.status === 404) return null;
    throw error;
  }
}

/** Newest first, as the site gives them. null when the site does not hold the item. */
export async function listRevisions(env: Env, project: SiteProject, itemId: string, fetcher?: typeof fetch): Promise<Revision[] | null> {
  requireRead(project);
  const list = await orNull(() => siteClient(env, project.site, fetcher).revisions(itemId));
  return list ? list.items : null;
}

/** The source as it was at a version. null when the site does not hold the item or the version. */
export async function readRevision(env: Env, project: SiteProject, itemId: string, version: string, fetcher?: typeof fetch): Promise<string | null> {
  requireRead(project);
  const revision = await orNull(() => siteClient(env, project.site, fetcher).revision(itemId, version));
  return revision ? revision.source : null;
}

/** The site's own unified patch from one version to another. null when the site does not hold either. */
export async function revisionPatch(env: Env, project: SiteProject, itemId: string, from: string, to: string, fetcher?: typeof fetch): Promise<string | null> {
  requireRead(project);
  const diff = await orNull(() => siteClient(env, project.site, fetcher).diff(itemId, from, to));
  return diff ? diff.patch : null;
}

/**
 * Puts two picked versions in order, older first, by their place in the site's list (newest first).
 * null unless exactly two different versions that are both in the list were picked.
 */
export function orderPair(revisions: readonly Revision[], picked: readonly string[]): { from: Revision; to: Revision } | null {
  const unique = [...new Set(picked)];
  if (unique.length !== 2) return null;
  const at = (version: string) => revisions.findIndex((r) => r.version === version);
  const [a, b] = unique as [string, string];
  if (at(a) < 0 || at(b) < 0) return null;
  const [older, newer] = at(a) > at(b) ? [a, b] : [b, a];
  return { from: revisions[at(older)]!, to: revisions[at(newer)]! };
}

app/lib/novels/export.ts.source:
// Assembly and export (design section 5, "for sending a book out"): ePub (zipped XHTML) and Word
// built in the Worker, and PDF from the print page in the browser. Scenes are prose, so the Markdown
// they use is small: paragraphs, headings, block quotes, scene breaks, *emphasis* and **strong**.
// Anything else passes through as text rather than being guessed at.

import { AlignmentType, Document, HeadingLevel, Packer, PageBreak, Paragraph, TextRun } from "docx";
import { strToU8, zipSync, type Zippable } from "fflate";

import type { Assembled } from "~/lib/books.server";

export type Inline = { text: string; em: boolean; strong: boolean };
export type Block = { type: "p" | "quote"; inlines: Inline[] } | { type: "h"; level: number; inlines: Inline[] } | { type: "break" };

/** `*a* **b** _c_ __d__`, with a backslash escaping the next character. Unclosed markers are text. */
export function parseInline(text: string): Inline[] {
  const out: Inline[] = [];
  let em = false;
  let strong = false;
  let buf = "";
  const flush = () => {
    if (buf) out.push({ text: buf, em, strong });
    buf = "";
  };
  // Markers that have a partner later in the line; the rest are literal.
  const closes = (from: number, marker: string) => text.indexOf(marker, from) !== -1;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i]!;
    if (ch === "\\" && i + 1 < text.length) {
      buf += text[++i];
      continue;
    }
    if ((ch === "*" || ch === "_") && text[i + 1] === ch) {
      const marker = ch + ch;
      if (strong || closes(i + 2, marker)) {
        flush();
        strong = !strong;
        i++;
        continue;
      }
    } else if (ch === "*" || ch === "_") {
      // An underscore inside a word (snake_case) is text.
      const inWord = ch === "_" && /\w/.test(text[i - 1] ?? "") && /\w/.test(text[i + 1] ?? "");
      if (!inWord && (em || closes(i + 1, ch))) {
        flush();
        em = !em;
        continue;
      }
    }
    buf += ch;
  }
  flush();
  return out;
}

export function parseProse(body: string): Block[] {
  const blocks: Block[] = [];
  for (const chunk of body.replace(/\r\n/g, "\n").split(/\n\s*\n/)) {
    const raw = chunk.trim();
    if (!raw) continue;
    if (/^(?:\*\s*){3,}$|^(?:-\s*){3,}$|^(?:_\s*){3,}$|^#$/.test(raw)) {
      blocks.push({ type: "break" });
      continue;
    }
    const heading = /^(#{1,6})\s+(.*)$/.exec(raw);
    if (heading && !raw.includes("\n")) {
      blocks.push({ type: "h", level: heading[1]!.length, inlines: parseInline(heading[2]!.trim()) });
      continue;
    }
    if (raw.split("\n").every((l) => l.startsWith(">"))) {
      const text = raw.split("\n").map((l) => l.replace(/^>\s?/, "")).join(" ");
      blocks.push({ type: "quote", inlines: parseInline(text) });
      continue;
    }
    // Hard wraps inside a paragraph are one paragraph; a line ending in two spaces is not kept.
    blocks.push({ type: "p", inlines: parseInline(raw.split("\n").map((l) => l.trim()).join(" ")) });
  }
  return blocks;
}

// ---------- XHTML, for ePub and the print page

export function escapeXml(text: string): string {
  return text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
}

function inlineHtml(inlines: Inline[]): string {
  return inlines
    .map((i) => {
      let html = escapeXml(i.text);
      if (i.em) html = `<em>${html}</em>`;
      if (i.strong) html = `<strong>${html}</strong>`;
      return html;
    })
    .join("");
}

export function blocksToHtml(blocks: Block[]): string {
  return blocks
    .map((b) => {
      switch (b.type) {
        case "break":
          return `<p class="scene-break">* * *</p>`;
        case "h": {
          // Chapter titles are h1 in the assembled book, so a heading inside a scene sits below them.
          const level = Math.min(6, b.level + 1);
          return `<h${level}>${inlineHtml(b.inlines)}</h${level}>`;
        }
        case "quote":
          return `<blockquote><p>${inlineHtml(b.inlines)}</p></blockquote>`;
        default:
          return `<p>${inlineHtml(b.inlines)}</p>`;
      }
    })
    .join("\n");
}

/** A chapter's scenes, separated by scene breaks, as the chapter's body. */
export function chapterBlocks(chapter: Assembled["chapters"][number]): Block[] {
  const out: Block[] = [];
  chapter.scenes.forEach((scene, i) => {
    if (i > 0) out.push({ type: "break" });
    out.push(...parseProse(scene.body));
  });
  return out;
}

const BOOK_CSS = `body { font-family: Georgia, "Times New Roman", serif; line-height: 1.5; }
h1 { text-align: center; margin: 3em 0 2em; font-weight: normal; }
p { margin: 0; text-indent: 1.5em; }
h1 + p, h2 + p, .scene-break + p, blockquote + p { text-indent: 0; }
.scene-break { text-align: center; text-indent: 0; margin: 1em 0; }
blockquote { margin: 1em 2em; font-style: italic; }
`;

// ---------- ePub 3

export function slugFor(title: string): string {
  return title.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "book";
}

export function buildEpub(book: Assembled, opts: { id: string; modified: Date }): Uint8Array<ArrayBuffer> {
  const chapterFiles = book.chapters.map((c, i) => ({ file: `chapter-${String(i + 1).padStart(3, "0")}.xhtml`, chapter: c }));
  const xhtml = (title: string, body: string) =>
    `<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE html>
<html xmlns="http://www.w3.org/1999/xhtml" xmlns:epub="http://www.idpf.org/2007/ops" lang="${escapeXml(book.language)}" xml:lang="${escapeXml(book.language)}">
<head><meta charset="UTF-8"/><title>${escapeXml(title)}</title><link rel="stylesheet" type="text/css" href="book.css"/></head>
<body>
${body}
</body>
</html>
`;
  const modified = opts.modified.toISOString().replace(/\.\d{3}Z$/, "Z");
  const opf = `<?xml version="1.0" encoding="UTF-8"?>
<package xmlns="http://www.idpf.org/2007/opf" version="3.0" unique-identifier="book-id" xml:lang="${escapeXml(book.language)}">
  <metadata xmlns:dc="http://purl.org/dc/elements/1.1/">
    <dc:identifier id="book-id">urn:uuid:${escapeXml(opts.id)}</dc:identifier>
    <dc:title>${escapeXml(book.title)}</dc:title>
    <dc:creator>${escapeXml(book.author)}</dc:creator>
    <dc:language>${escapeXml(book.language)}</dc:language>
    <meta property="dcterms:modified">${modified}</meta>
  </metadata>
  <manifest>
    <item id="nav" href="nav.xhtml" media-type="application/xhtml+xml" properties="nav"/>
    <item id="css" href="book.css" media-type="text/css"/>
    <item id="title" href="title.xhtml" media-type="application/xhtml+xml"/>
${chapterFiles.map((c, i) => `    <item id="c${i + 1}" href="${c.file}" media-type="application/xhtml+xml"/>`).join("\n")}
  </manifest>
  <spine>
    <itemref idref="title"/>
${chapterFiles.map((_, i) => `    <itemref idref="c${i + 1}"/>`).join("\n")}
  </spine>
</package>
`;
  const nav = xhtml(
    book.title,
    `<nav epub:type="toc" id="toc"><h1>Contents</h1><ol>
${chapterFiles.map((c) => `<li><a href="${c.file}">${escapeXml(c.chapter.title)}</a></li>`).join("\n")}
</ol></nav>`,
  );
  const files: Zippable = {
    // The mimetype comes first and uncompressed, as the ePub container requires.
    mimetype: [strToU8("application/epub+zip"), { level: 0 }],
    "META-INF/container.xml": strToU8(`<?xml version="1.0" encoding="UTF-8"?>
<container version="1.0" xmlns="urn:oasis:names:tc:opendocument:xmlns:container">
  <rootfiles><rootfile full-path="OEBPS/content.opf" media-type="application/oebps-package+xml"/></rootfiles>
</container>
`),
    "OEBPS/content.opf": strToU8(opf),
    "OEBPS/nav.xhtml": strToU8(nav),
    "OEBPS/book.css": strToU8(BOOK_CSS),
    "OEBPS/title.xhtml": strToU8(xhtml(book.title, `<h1>${escapeXml(book.title)}</h1>\n<p class="scene-break">${escapeXml(book.author)}</p>`)),
  };
  for (const c of chapterFiles) {
    files[`OEBPS/${c.file}`] = strToU8(xhtml(c.chapter.title, `<h1>${escapeXml(c.chapter.title)}</h1>\n${blocksToHtml(chapterBlocks(c.chapter))}`));
  }
  // Copied into an ArrayBuffer-backed array, which a Response body requires.
  return new Uint8Array(zipSync(files));
}

// ---------- Word

function runs(inlines: Inline[]): TextRun[] {
  return inlines.map((i) => new TextRun({ text: i.text, italics: i.em, bold: i.strong }));
}

export async function buildDocx(book: Assembled): Promise<ArrayBuffer> {
  const children: Paragraph[] = [
    new Paragraph({ heading: HeadingLevel.TITLE, alignment: AlignmentType.CENTER, children: [new TextRun(book.title)] }),
    new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun(book.author)] }),
  ];
  for (const chapter of book.chapters) {
    children.push(new Paragraph({ children: [new PageBreak()] }));
    children.push(new Paragraph({ heading: HeadingLevel.HEADING_1, alignment: AlignmentType.CENTER, children: [new TextRun(chapter.title)] }));
    for (const b of chapterBlocks(chapter)) {
      if (b.type === "break") children.push(new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun("* * *")] }));
      else if (b.type === "h") children.push(new Paragraph({ heading: b.level <= 1 ? HeadingLevel.HEADING_2 : HeadingLevel.HEADING_3, children: runs(b.inlines) }));
      else if (b.type === "quote") children.push(new Paragraph({ indent: { left: 720, right: 720 }, children: runs(b.inlines) }));
      else children.push(new Paragraph({ indent: { firstLine: 360 }, children: runs(b.inlines) }));
    }
  }
  const doc = new Document({ creator: book.author, title: book.title, sections: [{ children }] });
  return Packer.toArrayBuffer(doc);
}

// ---------- the print page, for PDF from the browser

export function printHtml(book: Assembled): string {
  const chapters = book.chapters
    .map((c) => `<section class="chapter"><h1>${escapeXml(c.title)}</h1>\n${blocksToHtml(chapterBlocks(c))}</section>`)
    .join("\n");
  return `<!doctype html>
<html lang="${escapeXml(book.language)}">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeXml(book.title)}</title>
<style>
${BOOK_CSS}
body { max-width: 34rem; margin: 2rem auto; padding: 0 1rem; font-size: 12pt; }
.title-page { text-align: center; margin: 30vh 0; }
.chapter { break-before: page; }
.hint { font-family: system-ui, sans-serif; font-size: 10pt; color: #555; border: 1px solid #ccc; padding: 0.5rem 0.75rem; }
@page { size: 6in 9in; margin: 0.75in; }
@media print { .hint { display: none; } body { margin: 0; max-width: none; } }
</style>
</head>
<body>
<p class="hint">Print this page and choose Save as PDF. The page size is 6 by 9 inches.</p>
<section class="title-page"><h1>${escapeXml(book.title)}</h1><p class="scene-break">${escapeXml(book.author)}</p></section>
${chapters}
</body>
</html>
`;
}

app/routes/media.api.ts.source:
// The editor's media endpoint for one project (stage 3): GET lists the site's files for the library
// picker, POST uploads one file for the editor's paste, drop or Insert image. JSON both ways, so the
// editor reads an answer and never an HTML page. The roles are the library's: a Reader may list, and
// only an Editor or the Owner uploads.

import { SiteApiError } from "@dustinedwards/site-api/client";

import { getEnv, getViewer } from "~/lib/context";
import { listMedia, uploadMedia } from "~/lib/media.server";
import { requireSiteProject } from "~/lib/projects.server";
import { SiteNotConnected } from "~/lib/sites.server";

import type { Route } from "./+types/media.api";

function unreachable(error: unknown): string | null {
  if (error instanceof SiteNotConnected) return `The site is not connected: ${error.detail}`;
  if (error instanceof SiteApiError) return error.body ? `The site refused: ${error.body.message}` : `The site answered ${error.status}.`;
  return null;
}

export async function loader({ params, request, context }: Route.LoaderArgs) {
  const env = getEnv(context);
  const project = await requireSiteProject(env.DB, getViewer(context), params.project, "read");
  const url = new URL(request.url);
  try {
    return Response.json(
      await listMedia(env, project, {
        q: url.searchParams.get("q")?.trim().slice(0, 200) || undefined,
        cursor: url.searchParams.get("cursor") || undefined,
        limit: 60,
      }),
    );
  } catch (error) {
    const message = unreachable(error);
    if (message === null) throw error;
    return Response.json({ items: [], nextCursor: null, error: message });
  }
}

export async function action({ params, request, context }: Route.ActionArgs) {
  const env = getEnv(context);
  // Refused on the role before the body is read: a Reader's upload never reaches the site.
  const viewer = getViewer(context);
  const project = await requireSiteProject(env.DB, viewer, params.project, "edit");
  if (request.method !== "POST") return Response.json({ error: "Method not allowed." }, { status: 405 });
  const form = await request.formData();
  const file = form.get("file");
  if (!(file instanceof File)) return Response.json({ error: "No file was chosen." }, { status: 400 });
  try {
    const outcome = await uploadMedia(
      env,
      project,
      { viewer },
      { name: file.name, type: file.type, size: file.size, bytes: () => file.arrayBuffer() },
      String(form.get("alt") ?? ""),
    );
    if (!outcome.ok) return Response.json({ error: outcome.message }, { status: 422 });
    return Response.json({ id: outcome.item.id, url: outcome.item.url, src: outcome.item.src }, { status: 201 });
  } catch (error) {
    const message = unreachable(error);
    if (message === null) throw error;
    return Response.json({ error: message }, { status: 502 });
  }
}

app/routes/unpublish.tsx.source:
// Where the email after an AI publish sends Dustin: the post, who published it, and one button that
// returns it to draft. The link opens this page rather than unpublishing on its own, because a GET
// that changed the site could be set off by anything that fetches links (a mail client's preview).

import { Form, Link, useNavigation } from "react-router";
import { Alert, Banner } from "capsomer/react/banner";
import { Button } from "capsomer/react/button";
import { Pill } from "capsomer/react/status";
import { Time } from "capsomer/react/time";

import { PageHead } from "~/components/page-head";

import { lastAiPublication, publishedByLine } from "~/lib/ai.server";
import { readDoc, writeToSite } from "~/lib/content.server";
import { getEnv, getViewer } from "~/lib/context";
import { requireSiteProject } from "~/lib/projects.server";
import { siteEntry } from "~/lib/sites.server";

import type { Route } from "./+types/unpublish";

export function meta() {
  return [{ title: "Unpublish · Carrel" }];
}

export async function loader({ params, context }: Route.LoaderArgs) {
  const env = getEnv(context);
  const project = await requireSiteProject(env.DB, getViewer(context), params.project, "publish");
  const doc = await readDoc(env, project, params.item);
  if (!doc) throw new Response("Not found", { status: 404 });
  const ai = await lastAiPublication(env.DB, project, params.item);
  return {
    project: { slug: project.slug, name: project.name, site: siteEntry(project.site).name },
    item: { id: doc.id, title: doc.title || doc.id, status: doc.status, path: doc.path, version: doc.version },
    publishedBy: ai ? { line: publishedByLine(ai.client), at: ai.publishedAt } : null,
  };
}

export async function action({ params, context }: Route.ActionArgs) {
  const env = getEnv(context);
  const viewer = getViewer(context);
  const project = await requireSiteProject(env.DB, viewer, params.project, "publish");
  const doc = await readDoc(env, project, params.item);
  if (!doc) throw new Response("Not found", { status: 404 });
  if (doc.status === "draft") return { ok: true as const, already: true, message: "It is already a draft." };
  const outcome = await writeToSite(env, project, viewer, params.item, { action: "unpublish", expectedVersion: doc.version });
  return outcome.ok ? { ok: true as const, already: false, message: "Returned to draft. It is off the site." } : { ok: false as const, already: false, message: outcome.message };
}

export default function Unpublish({ loaderData, actionData }: Route.ComponentProps) {
  const { project, item, publishedBy } = loaderData;
  const done = actionData?.ok;
  const busy = useNavigation().state !== "idle";
  return (
    <div className="app-page" data-narrow>
      <PageHead
        crumbs={[{ label: project.name, href: `/p/${project.slug}` }, { label: item.title }]}
        title={item.title}
        lead={
          <>
            {item.status === "published" ? <Pill tone="ok">Published</Pill> : item.status === "scheduled" ? <Pill tone="info">Scheduled</Pill> : <Pill variant="secondary">Draft</Pill>} on {project.site}
            {item.path ? <span className="cap-mono"> {item.path}</span> : null}
          </>
        }
      />
      {publishedBy ? (
        <Banner tone="info">
          {publishedBy.line} <Time at={publishedBy.at} format="exact" />
        </Banner>
      ) : null}
      {actionData ? actionData.ok ? <Banner tone="ok">{actionData.message}</Banner> : <Alert tone="crit">{actionData.message}</Alert> : null}
      <div className="app-actions">
        {!done && item.status !== "draft" ? (
          <Form method="post">
            <Button type="submit" variant="danger" pending={busy} autoFocus>
              Unpublish now
            </Button>
          </Form>
        ) : null}
        <Link className="cap-btn" to={`/p/${project.slug}/e/${encodeURIComponent(item.id)}`}>
          Open it in the editor
        </Link>
      </div>
    </div>
  );
}

app/lib/save-state.ts.source:
/** What the site holds, in words that do not read as live when it is not: a draft on the site is not published. */
export function siteState(status: "draft" | "scheduled" | "published" | null, everPublished: boolean): string {
  if (status === "published") return "Matches the live post";
  if (status === "scheduled") return "Matches the site, scheduled to publish";
  return everPublished ? "Matches the site's draft. It is not live." : "Saved as a draft on the site. Not published yet.";
}

