// The people page, the project flags list and media in the authorship record (job_11a70a5353a3).
// Each refusal the job names is planted, and each checks that nothing changed.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { deleteMedia, uploadMedia } from "~/lib/media.server";
import { addPerson as adminAddPerson, listPeople, PeopleRefusal, setDisabled, setProjectRole } from "~/lib/people-admin.server";
import { findViewer } from "~/lib/people.server";
import { requireSiteProject } from "~/lib/projects.server";
import { action as peopleAction, loader as peopleLoader } from "~/routes/people";
import { action as flagsAction, loader as flagsLoader } from "~/routes/project.flags";

import { addPerson, addProject, resetDb, share, testEnv } from "./env";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const SLUG = "de-info";
let projectId: number;

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  const reader = await addPerson("reader@test.invalid");
  const reviewer = await addPerson("reviewer@test.invalid", { reviewer: true });
  await addPerson("stranger@test.invalid");
  projectId = await addProject(SLUG, "dustinedwards");
  await share(projectId, editor, "editor");
  await share(projectId, reader, "reader");
  await share(projectId, reviewer, "reader");
});

async function contextFor(email: string, env: Env = testEnv) {
  const context = new RouterContextProvider();
  context.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
  context.set(viewerContext, await viewerFor(email));
  context.set(nonceContext, "n");
  return context;
}

async function status(run: () => Promise<unknown>): Promise<number> {
  try {
    await run();
    return 200;
  } catch (thrown) {
    if (thrown instanceof Response) return thrown.status;
    throw thrown;
  }
}

/** Every people and membership row, to prove a refusal changed nothing. */
async function snapshot() {
  const [p, m] = await Promise.all([
    testEnv.DB.prepare("SELECT id, email, is_owner, is_reviewer, disabled_at FROM people ORDER BY id").all(),
    testEnv.DB.prepare("SELECT project_id, person_id, role FROM project_members ORDER BY project_id, person_id").all(),
  ]);
  return JSON.stringify([p.results, m.results]);
}

function form(fields: Record<string, string>) {
  const body = new FormData();
  for (const [k, v] of Object.entries(fields)) body.set(k, v);
  return new Request("https://carrel.test/people", { method: "POST", body });
}

async function personId(email: string) {
  return (await testEnv.DB.prepare("SELECT id FROM people WHERE email = ?").bind(email).first<{ id: number }>())!.id;
}

describe("the people page", () => {
  it("lists everyone with their kind and their role on each project, the Owner first", async () => {
    const data = await listPeople(testEnv.DB, await viewerFor("owner@test.invalid"));
    expect(data.people[0]).toMatchObject({ email: "owner@test.invalid", isOwner: true });
    expect(data.people.find((p) => p.email === "editor@test.invalid")).toMatchObject({ roles: [{ projectId, role: "editor" }] });
    expect(data.people.find((p) => p.email === "reviewer@test.invalid")).toMatchObject({ isReviewer: true, roles: [{ role: "reader" }] });
    expect(data.projects).toEqual([{ id: projectId, slug: SLUG, name: SLUG, kind: "site" }]);
  });

  it("adds a person, shares a project with them, changes and removes the role, disables and enables them", async () => {
    const context = await contextFor("owner@test.invalid");
    expect(await peopleAction({ request: form({ intent: "add", email: " Wife@Test.Invalid ", name: "Wife", reviewer: "no" }), params: {}, context } as never)).toEqual({
      ok: true,
      intent: "add",
      added: "wife@test.invalid",
    });
    const id = await personId("wife@test.invalid");
    await peopleAction({ request: form({ intent: "role", person: String(id), project: String(projectId), role: "reader" }), params: {}, context } as never);
    await peopleAction({ request: form({ intent: "role", person: String(id), project: String(projectId), role: "editor" }), params: {}, context } as never);
    expect(await testEnv.DB.prepare("SELECT role FROM project_members WHERE person_id = ?").bind(id).first()).toEqual({ role: "editor" });
    await peopleAction({ request: form({ intent: "role", person: String(id), project: String(projectId), role: "" }), params: {}, context } as never);
    expect(await testEnv.DB.prepare("SELECT COUNT(*) AS n FROM project_members WHERE person_id = ?").bind(id).first()).toEqual({ n: 0 });

    await peopleAction({ request: form({ intent: "disable", person: String(id) }), params: {}, context } as never);
    // Disabled means refused at both doors, since every request looks the person up again.
    expect(await findViewer(testEnv.DB, "wife@test.invalid")).toBeNull();
    await peopleAction({ request: form({ intent: "enable", person: String(id) }), params: {}, context } as never);
    expect(await findViewer(testEnv.DB, "wife@test.invalid")).toMatchObject({ email: "wife@test.invalid" });
  });

  it("refuses an email already in Carrel, and one that is not an email", async () => {
    const owner = await viewerFor("owner@test.invalid");
    const before = await snapshot();
    await expect(adminAddPerson(testEnv.DB, owner, { email: "EDITOR@test.invalid", name: "", reviewer: false })).rejects.toBeInstanceOf(PeopleRefusal);
    await expect(adminAddPerson(testEnv.DB, owner, { email: "not an email", name: "", reviewer: false })).rejects.toBeInstanceOf(PeopleRefusal);
    expect(await snapshot()).toBe(before);
  });
});

describe("PLANT: a non-Owner at the people page", () => {
  for (const email of ["editor@test.invalid", "reader@test.invalid", "reviewer@test.invalid", "stranger@test.invalid"]) {
    it(`answers ${email} 404 for the page and every action, and nothing changes`, async () => {
      const before = await snapshot();
      const context = await contextFor(email);
      const target = String(await personId("reader@test.invalid"));
      expect(await status(() => peopleLoader({ request: new Request("https://carrel.test/people"), params: {}, context } as never))).toBe(404);
      for (const fields of <Record<string, string>[]>[
        { intent: "add", email: "new@test.invalid", name: "", reviewer: "no" },
        { intent: "role", person: target, project: String(projectId), role: "editor" },
        { intent: "disable", person: target },
      ]) {
        expect(await status(() => peopleAction({ request: form(fields), params: {}, context } as never)), fields.intent).toBe(404);
      }
      expect(await snapshot()).toBe(before);
    });
  }
});

describe("PLANT: the Owner's own row", () => {
  it("refuses a second Owner: the page has no way to make one, and the database refuses one too", async () => {
    const context = await contextFor("owner@test.invalid");
    // Even a forged form field cannot make an Owner: addPerson has no such input.
    await peopleAction({ request: form({ intent: "add", email: "second@test.invalid", name: "", reviewer: "no", owner: "yes", is_owner: "1" }), params: {}, context } as never);
    expect(await testEnv.DB.prepare("SELECT COUNT(*) AS n FROM people WHERE is_owner = 1").first()).toEqual({ n: 1 });
    await expect(testEnv.DB.prepare("UPDATE people SET is_owner = 1 WHERE email = 'second@test.invalid'").run()).rejects.toThrow(/UNIQUE/);
  });

  it("refuses the Owner disabling themself, and changing the Owner's role, and nothing changes", async () => {
    const owner = await viewerFor("owner@test.invalid");
    const before = await snapshot();
    await expect(setDisabled(testEnv.DB, owner, owner.id, true)).rejects.toThrow("The Owner cannot be disabled.");
    await expect(setProjectRole(testEnv.DB, owner, owner.id, projectId, "reader")).rejects.toThrow(/Owner's role cannot be changed/);
    const answer = await peopleAction({ request: form({ intent: "disable", person: String(owner.id) }), params: {}, context: await contextFor("owner@test.invalid") } as never);
    expect(answer).toEqual({ ok: false, intent: "disable", message: "The Owner cannot be disabled." });
    expect(await snapshot()).toBe(before);
  });
});

describe("PLANT: a reviewer given the Editor role", () => {
  it("is refused (reviewers read and flag only), and nothing changes; Reader is allowed", async () => {
    const owner = await viewerFor("owner@test.invalid");
    const reviewer = await personId("reviewer@test.invalid");
    await setProjectRole(testEnv.DB, owner, reviewer, projectId, null);
    const before = await snapshot();
    await expect(setProjectRole(testEnv.DB, owner, reviewer, projectId, "editor")).rejects.toThrow(/Reviewers read and flag only/);
    expect(await snapshot()).toBe(before);
    await setProjectRole(testEnv.DB, owner, reviewer, projectId, "reader");
    expect(await testEnv.DB.prepare("SELECT role FROM project_members WHERE person_id = ?").bind(reviewer).first()).toEqual({ role: "reader" });
  });
});

// ---------- the project flags list

async function flag(path: string, message: string, check = "ai") {
  const row = await testEnv.DB.prepare("INSERT INTO findings (project_id, path, check_name, message, fingerprint) VALUES (?, ?, ?, ?, ?) RETURNING id")
    .bind(projectId, path, check, message, `${path}:${message}`)
    .first<{ id: number }>();
  return row!.id;
}

async function indexed(itemId: string, title: string) {
  await testEnv.DB.prepare("INSERT INTO site_items (project_id, item_id, kind, title, status, synced_at) VALUES (?, ?, 'post', ?, 'draft', '2026-09-27T00:00:00Z')")
    .bind(projectId, itemId, title)
    .run();
}

function dismissForm(id: number, item: string) {
  const body = new FormData();
  body.set("intent", "dismiss");
  body.set("flag", String(id));
  body.set("item", item);
  return new Request(`https://carrel.test/p/${SLUG}/flags`, { method: "POST", body });
}

describe("the project flags list", () => {
  it("lists every flag, open first, including one on an item the site does not have", async () => {
    await indexed("real-post", "A real post");
    const proof = await flag("carrel-mcp-proof", "Proof flag (from Claude Code)");
    const real = await flag("real-post", "A claim with no source (from Grok Build)", "review");
    const owner = await viewerFor("owner@test.invalid");
    await (await import("~/lib/ai.server")).dismissItemFinding(testEnv.DB, await requireSiteProject(testEnv.DB, owner, SLUG, "publish"), owner, "real-post", real);
    const data = (await flagsLoader({ params: { project: SLUG }, context: await contextFor("reader@test.invalid") } as never)) as { canDismiss: boolean; flags: { id: number; onSite: boolean; status: string; title: string | null }[] };
    expect(data.canDismiss).toBe(false);
    expect(data.flags.map((f) => [f.id, f.status, f.onSite, f.title])).toEqual([
      [proof, "open", false, null],
      [real, "dismissed", true, "A real post"],
    ]);
  });

  it("lets the Owner dismiss a flag on an item the site does not have, recorded as the editor records it, and it stays dismissed", async () => {
    const proof = await flag("carrel-mcp-proof", "Proof flag (from Claude)");
    const owner = await viewerFor("owner@test.invalid");
    expect(await flagsAction({ request: dismissForm(proof, "carrel-mcp-proof"), params: { project: SLUG }, context: await contextFor("owner@test.invalid") } as never)).toEqual({ dismissed: proof });
    const row = await testEnv.DB.prepare("SELECT status, dismissed_by, dismissed_at FROM findings WHERE id = ?").bind(proof).first<{ status: string; dismissed_by: number; dismissed_at: string }>();
    expect(row).toMatchObject({ status: "dismissed", dismissed_by: owner.id });
    expect(row!.dismissed_at).toMatch(/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d\.\d{3}Z$/);
    const again = (await flagsLoader({ params: { project: SLUG }, context: await contextFor("owner@test.invalid") } as never)) as { flags: { id: number; status: string }[] };
    expect(again.flags).toEqual([expect.objectContaining({ id: proof, status: "dismissed" })]);
  });

  it("PLANT: an Editor or a Reader cannot dismiss, a stranger sees nothing, and the flag stays open", async () => {
    const proof = await flag("carrel-mcp-proof", "Proof flag");
    for (const [email, code] of [["editor@test.invalid", 403], ["reader@test.invalid", 403], ["stranger@test.invalid", 404]] as const) {
      expect(await status(async () => flagsAction({ request: dismissForm(proof, "carrel-mcp-proof"), params: { project: SLUG }, context: await contextFor(email) } as never)), email).toBe(code);
    }
    expect(await status(async () => flagsLoader({ params: { project: SLUG }, context: await contextFor("stranger@test.invalid") } as never))).toBe(404);
    expect(await testEnv.DB.prepare("SELECT status, dismissed_by FROM findings WHERE id = ?").bind(proof).first()).toEqual({ status: "open", dismissed_by: null });
  });

  // Two layers refuse a non-Owner: the route (by role, before it reads the form) and the dismiss
  // function itself. Each is tested on its own, so removing either one is seen.
  it("PLANT: the route refuses a non-Owner by role before it reads the form", async () => {
    const empty = new Request(`https://carrel.test/p/${SLUG}/flags`, { method: "POST", body: new FormData() });
    // With the role check, 403. Without it, the missing fields would answer 400 instead.
    expect(await status(async () => flagsAction({ request: empty, params: { project: SLUG }, context: await contextFor("editor@test.invalid") } as never))).toBe(403);
  });

  it("PLANT: the dismiss function refuses a non-Owner on its own, whatever route calls it", async () => {
    const proof = await flag("carrel-mcp-proof", "Proof flag");
    const editor = await viewerFor("editor@test.invalid");
    const { dismissItemFinding } = await import("~/lib/ai.server");
    const project = await requireSiteProject(testEnv.DB, editor, SLUG, "read");
    expect(await status(() => dismissItemFinding(testEnv.DB, project, editor, "carrel-mcp-proof", proof))).toBe(403);
    expect(await testEnv.DB.prepare("SELECT status FROM findings WHERE id = ?").bind(proof).first()).toEqual({ status: "open" });
  });

  it("refuses a flag named with the wrong item, so a form cannot dismiss another item's flag", async () => {
    const proof = await flag("carrel-mcp-proof", "Proof flag");
    expect(await status(async () => flagsAction({ request: dismissForm(proof, "some-other-item"), params: { project: SLUG }, context: await contextFor("owner@test.invalid") } as never))).toBe(404);
    expect(await testEnv.DB.prepare("SELECT status FROM findings WHERE id = ?").bind(proof).first()).toEqual({ status: "open" });
  });
});

// ---------- media in the authorship record

const PNG = Uint8Array.from(
  atob("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg=="),
  (c) => c.charCodeAt(0),
);

describe("media in the authorship record", () => {
  let site: ReturnType<typeof fakeSite>;
  let env: Env;

  beforeEach(() => {
    site = fakeSite();
    env = connectedEnv();
    vi.stubGlobal("fetch", site.fetch);
  });

  const rows = () => testEnv.DB.prepare("SELECT id, item_id, person_id, action, version_before, version_after, client FROM changes ORDER BY created_at").all().then((r) => r.results);
  const file = (bytes: Uint8Array, name = "river.png", type = "image/png") => ({ name, type, size: bytes.byteLength, bytes: async () => bytes.slice().buffer });

  it("writes exactly one row for an upload and one for a delete, crediting the person and an AI client", async () => {
    const editor = await viewerFor("editor@test.invalid");
    const up = await uploadMedia(env, await requireSiteProject(env.DB, editor, SLUG, "edit"), { viewer: editor, client: "Claude Code" }, file(PNG), "The river");
    expect(up.ok).toBe(true);
    const id = up.ok ? up.item.id : "";
    expect(await rows()).toEqual([{ id: expect.any(String), item_id: id, person_id: editor.id, action: "media-upload", version_before: null, version_after: null, client: "Claude Code" }]);

    const owner = await viewerFor("owner@test.invalid");
    expect(await deleteMedia(env, await requireSiteProject(env.DB, owner, SLUG, "delete_media"), { viewer: owner }, id)).toEqual({ ok: true });
    expect((await rows()).map((r) => [r.action, r.item_id, r.person_id, r.client])).toEqual([
      ["media-upload", id, editor.id, "Claude Code"],
      ["media-delete", id, owner.id, null],
    ]);
  });

  it("PLANT: a refused delete, a refused upload and a role refusal write no row", async () => {
    const owner = await viewerFor("owner@test.invalid");
    const item = await site.adapter.media!.upload({ bytes: PNG, contentType: "image/png", filename: "cover.png", alt: "", changeId: "seed" });
    await site.adapter.content.saveDraft("river-post", { source: `# The river\n\n![](${item.url})\n`, expectedVersion: null, changeId: "c1" });
    const project = await requireSiteProject(env.DB, owner, SLUG, "delete_media");
    expect(await deleteMedia(env, project, { viewer: owner }, item.id)).toMatchObject({ ok: false, usedBy: [{ id: "river-post" }] });
    expect(await uploadMedia(env, project, { viewer: owner }, file(new TextEncoder().encode("<p>x</p>"), "x.html", "text/html"), "")).toMatchObject({ ok: false });
    const reader = await viewerFor("reader@test.invalid");
    expect(await status(async () => uploadMedia(env, await requireSiteProject(env.DB, reader, SLUG, "read"), { viewer: reader }, file(PNG), ""))).toBe(403);
    expect(await rows()).toEqual([]);
  });

  it("still requires a version for every content write (migration 0007 keeps that rule)", async () => {
    const owner = await personId("owner@test.invalid");
    await expect(
      testEnv.DB.prepare("INSERT INTO changes (id, project_id, item_id, person_id, action, version_after) VALUES ('x', ?, 'post', ?, 'save', NULL)").bind(projectId, owner).run(),
    ).rejects.toThrow(/CHECK/);
    await testEnv.DB.prepare("INSERT INTO changes (id, project_id, item_id, person_id, action, version_after) VALUES ('y', ?, 'post', ?, 'save', 'v1')").bind(projectId, owner).run();
  });
});

test/agent-keys.test.ts.source:
// Named agent keys at the AI door (job_77fd33040bdd). An agent that cannot complete OAuth (Grok Build)
// presents a key, and the key's Worker secret NAME is the agent: AGENT_KEY_GROK is "grok". The key
// says who is knocking and grants nothing: the agent is the person row "agent:grok" in People, its
// role comes from there, and it is credited as "agent:grok", never as Dustin. Every refusal below
// must end with nothing written, and each is planted in scripts/plant-gates.mjs or by hand (see the
// PR) and must turn the named test red.

import { createExecutionContext } from "cloudflare:test";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { agentPrincipal, keysMatch } from "~/lib/agent-keys.server";
import { addAgent, listPeople, PeopleRefusal, setProjectRole } from "~/lib/people-admin.server";
import { findAgentViewer } from "~/lib/people.server";
import { aiDoor } from "~/lib/mcp/door";

import { addPerson, addProject, resetDb, share, testEnv } from "./env";
import { MCP_HOST, modernRequest, readMessage, type ToolCallResult } from "./mcp-client";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const KEY = "grok-test-key-0123456789abcdefghijklmnop";
const OTHER_KEY = "other-test-key-0123456789abcdefghijklmnop";
const SLUG = "de-info";
const UNSHARED = "other-site";

let site: ReturnType<typeof fakeSite>;
let agentId: number;
let projectId: number;

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  agentId = await addPerson("agent:grok");
  projectId = await addProject(SLUG, "dustinedwards");
  await addProject(UNSHARED, "foxing");
  await share(projectId, agentId, "editor");
  site = fakeSite();
  vi.stubGlobal("fetch", site.fetch);
});

afterEach(() => vi.unstubAllGlobals());

const env = (extra: Record<string, string> = {}): Env => connectedEnv({ AGENT_KEY_GROK: KEY, ...extra });

async function door(request: Request, e: Env = env()) {
  return aiDoor(request, e, createExecutionContext());
}

function authed(authorization: string | null, name: string, args: Record<string, unknown> = {}, headers: Record<string, string> = {}) {
  return modernRequest(3, "tools/call", { name, arguments: args }, { ...(authorization ? { Authorization: authorization } : {}), ...headers });
}

async function call(name: string, args: Record<string, unknown> = {}, opts: { key?: string; env?: Env; headers?: Record<string, string> } = {}) {
  const response = await door(authed(`Bearer ${opts.key ?? KEY}`, name, args, opts.headers), opts.env);
  if (response.status !== 200) return { status: response.status, result: undefined as ToolCallResult | undefined };
  return { status: 200, result: (await readMessage(response)).result as unknown as ToolCallResult };
}

async function seedPost() {
  return (await site.adapter.content.saveDraft("post-one", { source: "---\ntitle: Post one\n---\nDustin's words.\n", expectedVersion: null, changeId: "seed" })).version;
}

const rows = async (sql: string) => (await testEnv.DB.prepare(sql).all()).results;

describe("what a named agent key does", () => {
  it("lets the agent read, save an AI draft beside Dustin's, flag and preview, credited as agent:grok", async () => {
    await seedPost();
    const listed = await call("list_projects");
    expect(listed.result!.structuredContent).toMatchObject({ projects: [{ slug: SLUG, role: "editor" }] });
    expect(((listed.result!.structuredContent as { projects: unknown[] }).projects).length).toBe(1);

    const saved = await call("save_draft", { project: SLUG, item: "post-one", source: "---\ntitle: Post one\n---\nGrok's try.\n", note: "A try." });
    expect(saved.result!.isError).toBeUndefined();
    expect(await rows("SELECT client, source FROM ai_drafts")).toEqual([{ client: "agent:grok", source: "---\ntitle: Post one\n---\nGrok's try.\n" }]);
    const owner = await viewerFor("owner@test.invalid");
    expect(await rows(`SELECT person_id FROM ai_drafts WHERE person_id = ${owner.id}`)).toEqual([]);
    expect(await rows(`SELECT person_id FROM ai_drafts WHERE person_id = ${agentId}`)).toHaveLength(1);

    const flagged = await call("add_finding", { project: SLUG, item: "post-one", message: "A flag." });
    expect(flagged.result!.structuredContent).toMatchObject({ flagged: true });
    expect(await rows("SELECT message FROM findings")).toEqual([{ message: "A flag. (from agent:grok)" }]);

    const preview = await call("preview", { project: SLUG, item: "post-one" });
    expect(preview.result!.isError).toBeUndefined();

    // Nothing reached the site's record: an agent's saved draft lives only in Carrel, and nothing is credited to Dustin.
    expect(await rows("SELECT id FROM changes")).toEqual([]);
    expect(site.requests.filter((r) => (r.startsWith("POST") || r.startsWith("PUT")) && !r.endsWith("/preview"))).toEqual([]);
  });

  it("PLANT: a key trying publish is refused with the Owner-only message, and nothing is published", async () => {
    const version = await seedPost();
    const { result } = await call("publish", { project: SLUG, item: "post-one", expected_version: version });
    expect(result).toMatchObject({ isError: true, content: [{ text: "Only the Owner's own sessions may publish." }] });
    expect((await site.adapter.content.get("post-one"))!.status).not.toBe("published");
    expect(await rows("SELECT * FROM ai_publications")).toEqual([]);
    expect(await rows("SELECT id FROM changes")).toEqual([]);
  });

  it("PLANT: the role is the person's role in People, never the key's: a Reader agent cannot save a draft", async () => {
    await seedPost();
    await testEnv.DB.prepare("UPDATE project_members SET role = 'reader' WHERE person_id = ?").bind(agentId).run();
    const { result } = await call("save_draft", { project: SLUG, item: "post-one", source: "x" });
    expect(result).toMatchObject({ isError: true, content: [{ text: "You may not write drafts on this project." }] });
    expect(await rows("SELECT id FROM ai_drafts")).toEqual([]);
  });

  it("PLANT: a project the agent has no role on is not there for it: not listed, not read, not drafted, not flagged", async () => {
    const { result: listed } = await call("list_projects");
    expect(JSON.stringify(listed!.structuredContent)).not.toContain(UNSHARED);
    for (const [name, args] of [
      ["search_items", {}],
      ["read_item", { item: "post-one" }],
      ["save_draft", { item: "post-one", source: "x" }],
      ["add_finding", { item: "post-one", message: "m" }],
      ["publish", { item: "post-one", expected_version: "v" }],
    ] as const) {
      const { result } = await call(name, { project: UNSHARED, ...args });
      expect(result, name).toMatchObject({ isError: true, content: [{ text: "Not found, or not shared with this person." }] });
    }
    expect(await rows("SELECT id FROM ai_drafts")).toEqual([]);
    expect(await rows("SELECT id FROM findings")).toEqual([]);
  });

  it("PLANT: a row marked Owner is never an agent: the key is refused", async () => {
    // The database allows one Owner, so the real one has to go before the agent's row can be flagged.
    await testEnv.DB.prepare("DELETE FROM people WHERE email = 'owner@test.invalid'").run();
    await testEnv.DB.prepare("UPDATE people SET is_owner = 1 WHERE email = 'agent:grok'").run();
    expect(await findAgentViewer(testEnv.DB, "grok")).toBeNull();
    expect((await call("list_projects")).status).toBe(403);
  });
});

describe("what a named agent key refuses", () => {
  it("PLANT: an unknown key is refused by the OAuth path: 401 with the Bearer challenge, nothing run", async () => {
    const response = await door(authed(`Bearer ${OTHER_KEY}`, "list_projects"));
    expect(response.status).toBe(401);
    expect(response.headers.get("WWW-Authenticate")).toContain("resource_metadata=");
    const near = await door(authed(`Bearer ${KEY}x`, "list_projects"));
    expect(near.status).toBe(401);
    const short = await door(authed(`Bearer ${KEY.slice(0, -1)}`, "list_projects"));
    expect(short.status).toBe(401);
  });

  it("PLANT: a key whose secret is absent is refused, and so is one that was revoked by deleting the secret", async () => {
    const without = connectedEnv();
    expect((await call("list_projects", {}, { env: without })).status).toBe(401);
    const revoked: Env = { ...env() };
    delete revoked.AGENT_KEY_GROK;
    expect((await call("list_projects", {}, { env: revoked })).status).toBe(401);
    // A blank secret admits nobody, and is not a key that matches the empty string.
    expect((await call("list_projects", {}, { env: env({ AGENT_KEY_GROK: "  " }), key: " " })).status).toBe(401);
  });

  it("PLANT: a key whose person row is disabled, or missing, is refused at once, and never falls through to OAuth", async () => {
    expect((await call("list_projects")).status).toBe(200);
    await testEnv.DB.prepare("UPDATE people SET disabled_at = '2026-10-07T00:00:00Z' WHERE email = 'agent:grok'").run();
    expect((await call("list_projects")).status).toBe(403);
    await testEnv.DB.prepare("DELETE FROM project_members").run();
    await testEnv.DB.prepare("DELETE FROM people WHERE email = 'agent:grok'").run();
    expect((await call("list_projects")).status).toBe(403);
    expect(await rows("SELECT id FROM ai_drafts")).toEqual([]);
  });

  it("PLANT: the agent's name is the secret's name, never the request's: a header or body naming another agent changes nothing", async () => {
    await addPerson("agent:other");
    await share(projectId, (await viewerFor("agent:other")).id, "editor");
    await seedPost();
    const claims = {
      "X-Agent": "other",
      "X-Agent-Name": "other",
      "X-Carrel-Agent": "agent:other",
      "X-Forwarded-User": "owner@test.invalid",
      "Cf-Access-Authenticated-User-Email": "owner@test.invalid",
      "Cf-Access-Jwt-Assertion": "x.y.z",
      "Mcp-Client": "agent:other",
    };
    const saved = await call("save_draft", { project: SLUG, item: "post-one", source: "x" }, { headers: claims });
    expect(saved.result!.isError).toBeUndefined();
    // A body that claims an identity is refused by the tool's own schema; nothing is written.
    for (const claim of [{ agent: "other" }, { client: "agent:other" }, { person: "owner@test.invalid" }]) {
      const refused = await door(authed(`Bearer ${KEY}`, "save_draft", { project: SLUG, item: "post-one", source: "y", ...claim }, claims));
      expect(JSON.stringify(await readMessage(refused)), JSON.stringify(claim)).toMatch(/error|invalid|unrecognized|additional/i);
    }
    expect(await rows("SELECT client FROM ai_drafts")).toEqual([{ client: "agent:grok" }]);
    // Two agents with two keys: each key is its own name, whichever the request claims to be.
    const second = await call("save_draft", { project: SLUG, item: "post-one", source: "z" }, { env: env({ AGENT_KEY_OTHER: OTHER_KEY }), key: OTHER_KEY, headers: { "X-Agent-Name": "grok" } });
    expect(second.result!.isError).toBeUndefined();
    expect((await rows("SELECT client FROM ai_drafts ORDER BY id")).map((r) => r.client)).toEqual(["agent:grok", "agent:other"]);
  });

  it("PLANT: a malformed Authorization header is never an agent: it goes to the OAuth path and is refused there", async () => {
    for (const header of [`Basic ${KEY}`, "Bearer", "Bearer ", `Bearer ${KEY} extra`, `Token ${KEY}`, KEY, `Bearer\t${KEY}`, ""]) {
      expect((await door(authed(header || null, "list_projects"))).status, header).toBe(401);
    }
    // The scheme is case-insensitive, as HTTP's is.
    expect((await door(authed(`bearer ${KEY}`, "list_projects"))).status).toBe(200);
  });

  it("is inert until a secret exists: with none, the door answers as it did before", async () => {
    const none = connectedEnv();
    expect(await agentPrincipal(none, `Bearer ${KEY}`)).toBeNull();
    const response = await door(modernRequest(1, "tools/list"), none);
    expect(response.status).toBe(401);
  });

  it("keeps the agent key to /mcp: another path on the door is never an agent's", async () => {
    for (const path of ["/", "/p/de-info", "/authorize", "/token", "/health"]) {
      const response = await door(new Request(`https://${MCP_HOST}${path}`, { headers: { Authorization: `Bearer ${KEY}` } }));
      if (path !== "/health") expect(response.status, path).toBeGreaterThanOrEqual(400);
      expect(await response.text(), path).not.toContain("projects");
    }
  });
});

describe("how the key is read", () => {
  it("names the agent from the secret's name, lower-cased, and only a valid name", async () => {
    expect(await agentPrincipal({ AGENT_KEY_GROK: KEY }, `Bearer ${KEY}`)).toBe("grok");
    expect(await agentPrincipal({ AGENT_KEY_Mixed_Case: KEY }, `Bearer ${KEY}`)).toBe("mixed_case");
    for (const name of ["AGENT_KEY_", "AGENT_KEY_has space", "AGENT_KEY_" + "x".repeat(33), "AGENT_KEY_-lead", "NOT_AGENT_KEY_GROK", "agent_key_grok"]) {
      expect(await agentPrincipal({ [name]: KEY }, `Bearer ${KEY}`), name).toBeNull();
    }
    expect(await agentPrincipal({ AGENT_KEY_GROK: 7 as unknown as string }, `Bearer 7`)).toBeNull();
  });

  it("picks the right agent among several and refuses a key that is none of them", async () => {
    const e = { AGENT_KEY_GROK: KEY, AGENT_KEY_OTHER: OTHER_KEY };
    expect(await agentPrincipal(e, `Bearer ${OTHER_KEY}`)).toBe("other");
    expect(await agentPrincipal(e, `Bearer ${KEY}`)).toBe("grok");
    expect(await agentPrincipal(e, "Bearer nope")).toBeNull();
    expect(await agentPrincipal(e, null)).toBeNull();
  });

  it("compares digests: equal keys match, and any difference in content or length does not", async () => {
    expect(await keysMatch(KEY, KEY)).toBe(true);
    expect(await keysMatch(KEY, `${KEY}x`)).toBe(false);
    expect(await keysMatch(KEY, KEY.slice(1))).toBe(false);
    expect(await keysMatch(KEY, OTHER_KEY)).toBe(false);
    expect(await keysMatch("", KEY)).toBe(false);
  });
});

describe("adding an agent in People", () => {
  it("is the Owner's alone, and the agent row is never an Owner or a reviewer, with no role until one is set", async () => {
    const owner = await viewerFor("owner@test.invalid");
    const added = await addAgent(testEnv.DB, owner, { name: " Claude-Two ", label: "Claude Two" });
    expect(added).toMatchObject({ email: "agent:claude-two", name: "Claude Two", isOwner: false, isReviewer: false, roles: [] });
    expect(await findAgentViewer(testEnv.DB, "claude-two")).toMatchObject({ email: "agent:claude-two" });

    const editor = await addPerson("editor@test.invalid");
    await share(projectId, editor, "editor");
    await expect(addAgent(testEnv.DB, await viewerFor("editor@test.invalid"), { name: "sneaky" })).rejects.toMatchObject({ status: 404 });
    await expect(addAgent(testEnv.DB, await viewerFor("agent:grok"), { name: "sneaky" })).rejects.toMatchObject({ status: 404 });
    expect(await rows("SELECT email FROM people WHERE email = 'agent:sneaky'")).toEqual([]);
  });

  it("refuses a duplicate and a name that is not a name, and changes nothing", async () => {
    const owner = await viewerFor("owner@test.invalid");
    const before = await rows("SELECT email FROM people");
    for (const name of ["grok", "GROK", "", "a b", "a@b.co", "-x", "x".repeat(33), "agent:x"]) {
      await expect(addAgent(testEnv.DB, owner, { name }), name).rejects.toBeInstanceOf(PeopleRefusal);
    }
    expect(await rows("SELECT email FROM people")).toEqual(before);
  });

  it("lists the agent and lets the Owner set its role like anyone's, Editor allowed", async () => {
    const owner = await viewerFor("owner@test.invalid");
    await addAgent(testEnv.DB, owner, { name: "fresh" });
    const fresh = (await viewerFor("agent:fresh")).id;
    await setProjectRole(testEnv.DB, owner, fresh, projectId, "editor");
    const { people } = await listPeople(testEnv.DB, owner);
    expect(people.find((p) => p.email === "agent:fresh")!.roles).toEqual([{ projectId, role: "editor" }]);
  });
});

test/history.test.ts.source:
// The history screens, driven through the route's loader with a real request context: a Reader may
// read all of it, nothing in it writes (to the site or to Carrel), and each comparison names the
// right two texts, older first.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { saveAiDraft } from "~/lib/ai.server";
import { autosave, writeToSite } from "~/lib/content.server";
import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { orderPair } from "~/lib/history.server";
import { hasChanges, unifiedPatch } from "~/lib/patch";
import { requireSiteProject } from "~/lib/projects.server";
import { loader as historyLoader } from "~/routes/history";

import { addPerson, addProject, resetDb, share, testEnv } from "./env";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const SLUG = "de-info";
let site: ReturnType<typeof fakeSite>;
let env: Env;
let versions: string[];

const V1 = "---\ntitle: Post one\n---\nFirst words.\n";
const V2 = "---\ntitle: Post one\n---\nFirst words, revised.\n";
const V3 = "---\ntitle: Post one\n---\nFirst words, revised.\n\nA new closing paragraph.\n";

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const reader = await addPerson("reader@test.invalid");
  await addPerson("stranger@test.invalid");
  const id = await addProject(SLUG, "dustinedwards");
  await share(id, reader, "reader");
  site = fakeSite();
  vi.stubGlobal("fetch", site.fetch);
  env = connectedEnv();
  const owner = await viewerFor("owner@test.invalid");
  const project = await requireSiteProject(testEnv.DB, owner, SLUG, "publish");
  versions = [];
  let expected: string | null = null;
  for (const source of [V1, V2, V3]) {
    const saved = await writeToSite(env, project, owner, "post-one", { action: "save", source, expectedVersion: expected }, site.fetch);
    if (!saved.ok) throw new Error(saved.message);
    expected = saved.version;
    versions.push(saved.version);
  }
  site.requests.length = 0;
});

async function load(email: string, search = "") {
  const context = new RouterContextProvider();
  context.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
  context.set(viewerContext, await viewerFor(email));
  context.set(nonceContext, "n");
  const request = new Request(`https://carrel.test/p/${SLUG}/e/post-one/history${search}`);
  return historyLoader({ request, params: { project: SLUG, item: "post-one" }, context } as never);
}

async function refusal(promise: Promise<unknown>): Promise<number> {
  try {
    await promise;
  } catch (thrown) {
    if (thrown instanceof Response) return thrown.status;
    throw thrown;
  }
  throw new Error("expected a refusal, and the call succeeded");
}

const changeRows = async () => (await testEnv.DB.prepare("SELECT COUNT(*) AS n FROM changes").first<{ n: number }>())!.n;

describe("reading history", () => {
  it("lists the revisions newest first for a Reader, and only reads", async () => {
    const before = await changeRows();
    const data = await load("reader@test.invalid");
    expect(data.revisions.map((r) => r.version)).toEqual([...versions].reverse());
    expect(data.revisions).toHaveLength(3);
    expect(site.requests.every((r) => r.startsWith("GET "))).toBe(true);
    expect(await changeRows()).toBe(before);
  });

  it("opens the source of an old revision", async () => {
    const data = await load("reader@test.invalid", `?version=${versions[0]}`);
    expect(data.view).toMatchObject({ kind: "source", source: V1, current: false, previous: null, newest: versions[2] });
    const newest = await load("reader@test.invalid", `?version=${versions[2]}`);
    expect(newest.view).toMatchObject({ kind: "source", source: V3, current: true, previous: versions[1], newest: null });
  });

  it("says plainly when the revision is not one the site holds", async () => {
    const data = await load("reader@test.invalid", "?version=nope");
    expect(data.view).toMatchObject({ kind: "problem", message: "The site has no such revision of this post." });
  });

  it("is answered 404 to someone with no role on the project, before the site is asked", async () => {
    expect(await refusal(load("stranger@test.invalid"))).toBe(404);
    expect(site.requests).toEqual([]);
  });
});

describe("comparing revisions", () => {
  it("sets the older revision against the newer whichever was picked first, from the site's own patch", async () => {
    const data = await load("reader@test.invalid", `?v=${versions[2]}&v=${versions[0]}`);
    expect(data.picked).toEqual([versions[0], versions[2]]);
    expect(data.view.kind).toBe("compare");
    const patch = (data.view as { patch: string }).patch;
    expect(patch).toContain("-First words.\n");
    expect(patch).toContain("+First words, revised.\n");
    expect(patch).toContain("+A new closing paragraph.\n");
    expect(site.requests).toContain("GET /api/carrel/v1/content/post-one/diff");
  });

  it("by word, hands the two revisions' texts to the word compare, older as Before", async () => {
    const data = await load("reader@test.invalid", `?v=${versions[0]}&v=${versions[1]}&by=word`);
    expect(data.view).toMatchObject({ kind: "compare", patch: null, before: { text: V1 }, after: { text: V2 } });
  });

  it("refuses one pick, the same pick twice and a pick the site does not hold, in words", async () => {
    for (const search of [`?v=${versions[0]}`, `?v=${versions[0]}&v=${versions[0]}`, `?v=${versions[0]}&v=nope`]) {
      const data = await load("reader@test.invalid", search);
      expect(data.view, search).toMatchObject({ kind: "problem", message: "Pick two different revisions to compare." });
    }
  });

  it("orders a pair by the site's list, newest first, so the older is always from", () => {
    const list = [
      { version: "c", at: "2026-10-03T00:00:00Z", author: "a", message: "" },
      { version: "b", at: "2026-10-02T00:00:00Z", author: "a", message: "" },
      { version: "a", at: "2026-10-01T00:00:00Z", author: "a", message: "" },
    ];
    expect(orderPair(list, ["c", "a"])).toMatchObject({ from: { version: "a" }, to: { version: "c" } });
    expect(orderPair(list, ["a", "c"])).toMatchObject({ from: { version: "a" }, to: { version: "c" } });
    expect(orderPair(list, ["a"])).toBeNull();
    expect(orderPair(list, ["a", "a"])).toBeNull();
    expect(orderPair(list, ["a", "z"])).toBeNull();
  });
});

describe("comparing the working draft", () => {
  async function ownDraft(source: string) {
    const owner = await viewerFor("owner@test.invalid");
    const project = await requireSiteProject(testEnv.DB, owner, SLUG, "edit");
    await autosave(testEnv.DB, project, owner, "post-one", { source, baseVersion: versions[2]! });
    return { owner, project };
  }

  it("sets the draft against the site's text with a patch built here, and the site is only read", async () => {
    await ownDraft(V3.replace("A new closing paragraph.", "A different closing paragraph."));
    const data = await load("owner@test.invalid", "?compare=site");
    expect(data.view.kind).toBe("compare");
    const patch = (data.view as { patch: string }).patch;
    expect(patch).toContain("-A new closing paragraph.\n");
    expect(patch).toContain("+A different closing paragraph.\n");
    expect(site.requests.every((r) => r.startsWith("GET "))).toBe(true);
  });

  it("says there is nothing to compare when the person has no working draft", async () => {
    const data = await load("owner@test.invalid", "?compare=site");
    expect(data.view).toMatchObject({ kind: "problem" });
    expect((data.view as { message: string }).message).toMatch(/no working draft/);
  });

  it("sets the draft against an AI draft, and a draft that is not the viewer's is not found", async () => {
    const { owner, project } = await ownDraft(V3);
    const saved = await saveAiDraft(env, project, { viewer: owner, client: "Claude Code" }, "post-one", { source: V3.replace("First words, revised.", "First words, tightened."), note: "" }, site.fetch);
    const data = await load("owner@test.invalid", `?compare=ai&ai=${saved.id}`);
    const view = data.view as { kind: string; heading: string; patch: string };
    expect(view.kind).toBe("compare");
    expect(view.heading).toContain("AI draft from Claude Code");
    expect(view.patch).toContain("-First words, revised.\n");
    expect(view.patch).toContain("+First words, tightened.\n");
    expect(await refusal(load("reader@test.invalid", `?compare=ai&ai=${saved.id}`))).toBe(404);
  });
});

describe("the local patch", () => {
  it("names both sides but one file, shows only the changed lines with context, and says nothing changed when nothing did", () => {
    const patch = unifiedPatch("post-one.md", { text: "a\nb\nc\nd\ne\nf\ng\nh\n", label: "On the site" }, { text: "a\nb\nc\nD\ne\nf\ng\nh\n", label: "Your draft" });
    expect(patch).toContain("--- post-one.md\tOn the site");
    expect(patch).toContain("+++ post-one.md\tYour draft");
    expect(patch).toContain("-d\n+D\n");
    expect(hasChanges(patch)).toBe(true);
    const same = unifiedPatch("post-one.md", { text: "same\n", label: "a" }, { text: "same\n", label: "b" });
    expect(hasChanges(same)).toBe(false);
  });
});

test/waiting.test.ts.source:
// Work waiting on a person that the site does not know yet: an AI draft for a new slug is listed in
// the project's Posts, opens in the editor and previews as the AI draft; an indexed post carries a
// count of AI drafts waiting. All of it private to the person the drafts belong to.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { saveAiDraft } from "~/lib/ai.server";
import { autosave } from "~/lib/content.server";
import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { refreshIndex } from "~/lib/index.server";
import { requireSiteProject } from "~/lib/projects.server";
import { titleOf } from "~/lib/waiting.server";
import { loader as editorLoader } from "~/routes/editor";
import { loader as previewLoader } from "~/routes/preview";
import { loader as projectLoader } from "~/routes/project";

import { addPerson, addProject, resetDb, share } from "./env";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const SLUG = "de-info";
let site: ReturnType<typeof fakeSite>;
let env: Env;
let projectId: number;

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  projectId = await addProject(SLUG, "dustinedwards");
  await share(projectId, editor, "editor");
  site = fakeSite();
  vi.stubGlobal("fetch", site.fetch);
  env = connectedEnv();
});

async function context(email: string) {
  const c = new RouterContextProvider();
  c.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
  c.set(viewerContext, await viewerFor(email));
  c.set(nonceContext, "n");
  return c;
}

async function aiDraft(email: string, item: string, source: string) {
  const viewer = await viewerFor(email);
  const project = await requireSiteProject(env.DB, viewer, SLUG, "edit");
  await saveAiDraft(env, project, { viewer, client: "Claude" }, item, { source });
}

async function list(email: string, query = "") {
  const request = new Request(`https://carrel.test/p/${SLUG}${query}`);
  return (await projectLoader({ request, params: { project: SLUG }, context: await context(email) } as never)).items;
}

const NEW_POST = "---\ntitle: A desk apart\n---\nWords for a new post.\n";

describe("the project's Posts list", () => {
  it("lists an AI draft for a post the site does not have, and its editor opens", async () => {
    await aiDraft("owner@test.invalid", "a-desk-apart", NEW_POST);
    const items = await list("owner@test.invalid");
    expect(items).toHaveLength(1);
    expect(items[0]).toMatchObject({ itemId: "a-desk-apart", title: "A desk apart", status: "draft", isNew: true, aiDrafts: 1 });

    const page = await editorLoader({ params: { project: SLUG, item: "a-desk-apart" }, context: await context("owner@test.invalid") } as never);
    expect(page.source).toBe("");
    expect(page.aiDrafts).toHaveLength(1);
  });

  it("includes it under the Draft filter and the search, and leaves it out of Published and a kind", async () => {
    await aiDraft("owner@test.invalid", "a-desk-apart", NEW_POST);
    expect(await list("owner@test.invalid", "?status=draft")).toHaveLength(1);
    expect(await list("owner@test.invalid", "?q=desk")).toHaveLength(1);
    expect(await list("owner@test.invalid", "?q=elephant")).toHaveLength(0);
    expect(await list("owner@test.invalid", "?status=published")).toHaveLength(0);
    expect(await list("owner@test.invalid", "?kind=post")).toHaveLength(0);
  });

  it("lists a draft of the person's own for a new post too", async () => {
    const owner = await viewerFor("owner@test.invalid");
    const project = await requireSiteProject(env.DB, owner, SLUG, "edit");
    await autosave(env.DB, project, owner, "mine", { source: "---\ntitle: Mine\n---\nx\n", baseVersion: null });
    const items = await list("owner@test.invalid");
    expect(items[0]).toMatchObject({ itemId: "mine", title: "Mine", isNew: true, ownDraft: true, aiDrafts: 0 });
  });

  it("marks an indexed post that has AI drafts waiting, with the count", async () => {
    const saved = await site.adapter.content.saveDraft("post-one", { source: "---\ntitle: Post one\n---\nOn the site.\n", expectedVersion: null, changeId: "s" });
    expect(saved.version).toBeTruthy();
    await refreshIndex(env, { id: projectId, site: "dustinedwards" });
    await aiDraft("owner@test.invalid", "post-one", "A better take.");
    await aiDraft("owner@test.invalid", "post-one", "Another take.");
    const items = await list("owner@test.invalid");
    expect(items).toHaveLength(1);
    expect(items[0]).toMatchObject({ itemId: "post-one", isNew: false, aiDrafts: 2 });
  });

  it("PLANT: shows nobody else's AI drafts, and the editor of one still answers 404", async () => {
    await aiDraft("editor@test.invalid", "a-desk-apart", NEW_POST);
    expect(await list("owner@test.invalid")).toHaveLength(0);
    await expect(editorLoader({ params: { project: SLUG, item: "a-desk-apart" }, context: await context("owner@test.invalid") } as never)).rejects.toMatchObject({ status: 404 });
  });
});

describe("the preview of an AI-draft-only post", () => {
  it("renders the AI draft through the site, labelled as an AI draft", async () => {
    await aiDraft("owner@test.invalid", "a-desk-apart", NEW_POST);
    const request = new Request(`https://carrel.test/p/${SLUG}/e/a-desk-apart/preview`);
    const response = (await previewLoader({ request, params: { project: SLUG, item: "a-desk-apart" }, context: await context("owner@test.invalid") } as never)) as Response;
    const html = await response.text();
    expect(html).toContain("A desk apart");
    expect(html).toContain("AI draft from Claude. It is not your draft and it is not on the site.");
  });

  it("still says there is nothing to preview when there is no AI draft either", async () => {
    const request = new Request(`https://carrel.test/p/${SLUG}/e/none/preview`);
    const response = (await previewLoader({ request, params: { project: SLUG, item: "none" }, context: await context("owner@test.invalid") } as never)) as Response;
    expect(await response.text()).toContain("There is nothing to preview yet.");
  });
});

describe("titleOf", () => {
  it("reads a plain or quoted frontmatter title, and nothing when there is none", () => {
    expect(titleOf("---\ntitle: Plain\n---\nx")).toBe("Plain");
    expect(titleOf('---\ntitle: "Quoted: yes"\n---\nx')).toBe("Quoted: yes");
    expect(titleOf("No frontmatter\ntitle: nope")).toBe("");
  });
});

test/routes.test.ts.source:
// The editor's routes, driven through their loaders and actions with a real request context: the
// preview is private to each person and sandboxed, and a first publish asks before it acts.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { autosave } from "~/lib/content.server";
import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { requireSiteProject } from "~/lib/projects.server";
import { action as editorAction } from "~/routes/editor";
import { loader as previewLoader } from "~/routes/preview";

import { addPerson, addProject, resetDb, share, testEnv } from "./env";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const SLUG = "de-info";

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  const reader = await addPerson("reader@test.invalid");
  await addPerson("stranger@test.invalid");
  const projectId = await addProject(SLUG, "dustinedwards");
  await share(projectId, editor, "editor");
  await share(projectId, reader, "reader");
});

async function contextFor(email: string, env: Env) {
  const context = new RouterContextProvider();
  context.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
  context.set(viewerContext, await viewerFor(email));
  context.set(nonceContext, "test-nonce");
  return context;
}

async function preview(email: string, env: Env) {
  const context = await contextFor(email, env);
  const request = new Request(`https://carrel.test/p/${SLUG}/e/post-one/preview`);
  try {
    return (await previewLoader({ request, params: { project: SLUG, item: "post-one" }, context } as never)) as Response;
  } catch (thrown) {
    if (thrown instanceof Response) return thrown;
    throw thrown;
  }
}

async function post(email: string, env: Env, fields: Record<string, string>) {
  const body = new FormData();
  for (const [k, v] of Object.entries(fields)) body.set(k, v);
  const request = new Request(`https://carrel.test/p/${SLUG}/e/post-one`, { method: "POST", body });
  return editorAction({ request, params: { project: SLUG, item: "post-one" }, context: await contextFor(email, env) } as never);
}

async function seedPost(site: ReturnType<typeof fakeSite>) {
  const saved = await site.adapter.content.saveDraft("post-one", { source: "---\ntitle: Site copy\n---\nOn the site.\n", expectedVersion: null, changeId: "seed" });
  return saved.version;
}

describe("the preview", () => {
  it("renders the viewer's own draft through the site, sandboxed and frameable by Carrel only", async () => {
    const site = fakeSite();
    vi.stubGlobal("fetch", site.fetch);
    const env = connectedEnv();
    const version = await seedPost(site);
    const owner = await viewerFor("owner@test.invalid");
    const project = await requireSiteProject(env.DB, owner, SLUG, "read");
    await autosave(env.DB, project, owner, "post-one", { source: "---\ntitle: Owner draft\n---\nNot on the site.\n", baseVersion: version });

    const response = await preview("owner@test.invalid", env);
    expect(response.status).toBe(200);
    expect(response.headers.get("Content-Security-Policy")).toMatch(/^sandbox; default-src 'none'/);
    expect(response.headers.get("X-Frame-Options")).toBe("SAMEORIGIN");
    const html = await response.text();
    expect(html).toContain("Owner draft");
    expect(html).toContain('<base href="https://site.test/">');
  });

  it("PLANT: never shows one person's working draft to another", async () => {
    const site = fakeSite();
    vi.stubGlobal("fetch", site.fetch);
    const env = connectedEnv();
    const version = await seedPost(site);
    const editor = await viewerFor("editor@test.invalid");
    const project = await requireSiteProject(env.DB, editor, SLUG, "edit");
    await autosave(env.DB, project, editor, "post-one", { source: "---\ntitle: Editor secret\n---\nx\n", baseVersion: version });

    const html = await (await preview("reader@test.invalid", env)).text();
    expect(html).toContain("Site copy");
    expect(html).not.toContain("Editor secret");
  });

  it("PLANT: refuses a non-member with the same 404 as a missing project", async () => {
    vi.stubGlobal("fetch", fakeSite().fetch);
    expect((await preview("stranger@test.invalid", connectedEnv())).status).toBe(404);
  });

  it("explains a site that is not connected inside the frame instead of failing", async () => {
    const response = await preview("owner@test.invalid", testEnv);
    expect(response.status).toBe(200);
    expect(await response.text()).toContain("not connected");
  });
});

describe("publishing from the editor", () => {
  it("asks before a first publish, and publishes on the explicit second ask", async () => {
    const site = fakeSite();
    vi.stubGlobal("fetch", site.fetch);
    const env = connectedEnv();
    const version = await seedPost(site);

    const ask = await post("owner@test.invalid", env, { intent: "publish", expectedVersion: version, source: "---\ntitle: Site copy\n---\nOn the site.\n" });
    expect(ask).toEqual({ intent: "publish", needsConfirm: true });
    expect(site.adapter.store.get("post-one")!.doc.status).toBe("draft");

    const done = await post("owner@test.invalid", env, {
      intent: "publish",
      confirm: "first-publish",
      expectedVersion: version,
      source: "---\ntitle: Site copy\n---\nOn the site.\n",
    });
    expect(done).toMatchObject({ intent: "write", outcome: { ok: true, status: "published" } });
  });

  it("PLANT: refuses an Editor's publish from the editor, confirmed or not", async () => {
    const site = fakeSite();
    vi.stubGlobal("fetch", site.fetch);
    const env = connectedEnv();
    const version = await seedPost(site);
    await expect(
      post("editor@test.invalid", env, { intent: "publish", confirm: "first-publish", expectedVersion: version, source: "x" }),
    ).rejects.toSatisfy((thrown: unknown) => thrown instanceof Response && thrown.status === 403);
    expect(site.adapter.store.get("post-one")!.doc.status).toBe("draft");
  });
});

test/kinds.test.ts.source:
// Every kind the site reports, end to end through the routes: a non-post kind lists under its own
// kind and filter, opens, saves, previews, publishes and shows its revisions exactly as a post does,
// and a data kind the site will not write stays out of the lists and, if reached, shows the site's
// own refusal. Carrel has no per-kind code; the kinds and paths come from the site.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { refreshIndex } from "~/lib/index.server";
import { action as editorAction, loader as editorLoader } from "~/routes/editor";
import { loader as historyLoader } from "~/routes/history";
import { loader as previewLoader } from "~/routes/preview";
import { loader as projectLoader } from "~/routes/project";

import { addPerson, addProject, resetDb } from "./env";
import { connectedEnv, fakeSite, kindedAdapter, viewerFor } from "./site";

const SLUG = "de-info";
const OWNER = "owner@test.invalid";
let projectId = 0;

beforeEach(async () => {
  await resetDb();
  await addPerson(OWNER, { owner: true });
  projectId = await addProject(SLUG, "dustinedwards");
});

async function contextFor(env: Env) {
  const context = new RouterContextProvider();
  context.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
  context.set(viewerContext, await viewerFor(OWNER));
  context.set(nonceContext, "test-nonce");
  return context;
}

async function settled<T>(run: () => Promise<T>): Promise<T | Response> {
  try {
    return await run();
  } catch (thrown) {
    if (thrown instanceof Response) return thrown;
    throw thrown;
  }
}

async function seeded() {
  const site = fakeSite(kindedAdapter());
  vi.stubGlobal("fetch", site.fetch);
  const env = connectedEnv();
  const put = async (id: string, source: string, publish: boolean) => {
    const saved = await site.adapter.content.saveDraft(id, { source, expectedVersion: null, changeId: `seed-${id}` });
    if (publish) await site.adapter.content.publish(id, { expectedVersion: saved.version, changeId: `seed-pub-${id}` });
  };
  await put("a-post", "---\ntitle: A post\n---\nWords.\n", true);
  await put("draft-post", "---\ntitle: A draft post\n---\nNot yet.\n", false);
  await put("phage.acorn15", "---\ntitle: Acorn15\nhost: Gordonia\n---\nA cluster DJ phage.\n", true);
  await put("roster.2017", "---\ntitle: 2017 cohort\nyear: 2017\n---\n", true);
  await put("procedure.coi-primers", "---\ntitle: COI primers\n---\nThe PCR protocol.\n", true);
  await refreshIndex(env, { id: projectId, site: "dustinedwards" });
  return { site, env };
}

const form = (fields: Record<string, string>) => {
  const body = new FormData();
  for (const [k, v] of Object.entries(fields)) body.set(k, v);
  return body;
};

describe("every kind the site reports", () => {
  it("lists each writing kind under its own kind, and the kind filter narrows to it", async () => {
    const { env } = await seeded();
    const context = await contextFor(env);
    const all = (await projectLoader({ request: new Request(`https://carrel.test/p/${SLUG}`), params: { project: SLUG }, context } as never)) as Awaited<ReturnType<typeof projectLoader>>;
    expect(all.kinds).toEqual(["phage", "post", "procedure", "roster"]);
    const byId = Object.fromEntries(all.items.map((i) => [i.itemId, i]));
    expect(byId["phage.acorn15"]).toMatchObject({ kind: "phage", path: "/research/phages#acorn15", status: "published" });
    expect(byId["roster.2017"]).toMatchObject({ kind: "roster", path: "/teaching/phage-discovery#year-2017" });
    expect(byId["procedure.coi-primers"]).toMatchObject({ kind: "procedure", path: "/research/protocols/coi-primers" });
    expect(byId["draft-post"]).toMatchObject({ kind: "post", status: "draft", path: null });

    const phages = (await projectLoader({ request: new Request(`https://carrel.test/p/${SLUG}?kind=phage`), params: { project: SLUG }, context } as never)) as Awaited<ReturnType<typeof projectLoader>>;
    expect(phages.items.map((i) => i.itemId)).toEqual(["phage.acorn15"]);
  });

  it("opens, saves, previews, publishes and shows the history of a non-post kind", async () => {
    const { env, site } = await seeded();
    const id = "phage.acorn15";
    const params = { project: SLUG, item: id };
    const url = `https://carrel.test/p/${SLUG}/e/${id}`;

    const opened = (await editorLoader({ request: new Request(url), params, context: await contextFor(env) } as never)) as Awaited<ReturnType<typeof editorLoader>>;
    expect(opened.title).toBe("Acorn15");
    expect(opened.path).toBe("/research/phages#acorn15");
    // Links written in the editor go to each item's own address on the site, a draft post to where the site's posts live.
    expect(opened.linkTargets.map((t) => t.href).sort()).toEqual([
      "/research/protocols/coi-primers",
      "/teaching/phage-discovery#year-2017",
      "/writing/a-post",
      "/writing/draft-post",
    ]);

    const source = "---\ntitle: Acorn15\nhost: Gordonia terrae\n---\nA cluster DJ phage, found in 2015.\n";
    const saved = await editorAction({ request: new Request(url, { method: "POST", body: form({ intent: "save", source, expectedVersion: opened.version! }) }), params, context: await contextFor(env) } as never);
    expect(saved).toMatchObject({ intent: "write", outcome: { ok: true, action: "save", status: "published" } });
    const version = (saved as { outcome: { version: string } }).outcome.version;

    const previewed = (await settled(async () => previewLoader({ request: new Request(`${url}/preview`), params, context: await contextFor(env) } as never))) as Response;
    expect(previewed.status).toBe(200);
    expect(await previewed.text()).toContain("found in 2015");

    const published = await editorAction({ request: new Request(url, { method: "POST", body: form({ intent: "publish", source, expectedVersion: version }) }), params, context: await contextFor(env) } as never);
    expect(published).toMatchObject({ intent: "write", outcome: { ok: true, action: "publish", status: "published" } });
    expect((await site.adapter.content.get(id))?.source).toContain("found in 2015");

    const history = (await historyLoader({ request: new Request(`${url}/history`), params, context: await contextFor(env) } as never)) as { revisions: unknown[] | null };
    expect(history.revisions?.length).toBe(4);
  });

  it("keeps a data kind out of the lists, and shows the site's own refusal if one is written", async () => {
    const { env, site } = await seeded();
    // The site's import puts registry rows in place directly; Carrel never wrote them.
    await env.DB.prepare("INSERT INTO site_items (project_id, item_id, kind, title, status, synced_at) VALUES (?, 'equipment.heat-block', 'equipment', 'Heat block', 'published', '2026-10-10T00:00:00Z')").bind(projectId).run();
    const context = await contextFor(env);
    const listed = (await projectLoader({ request: new Request(`https://carrel.test/p/${SLUG}`), params: { project: SLUG }, context } as never)) as Awaited<ReturnType<typeof projectLoader>>;
    expect(listed.kinds).not.toContain("equipment");
    expect(listed.items.map((i) => i.itemId)).not.toContain("equipment.heat-block");

    const params = { project: SLUG, item: "equipment.heat-block" };
    const written = await editorAction({
      request: new Request(`https://carrel.test/p/${SLUG}/e/equipment.heat-block`, { method: "POST", body: form({ intent: "save", source: "---\nname: Heat block\n---\n", expectedVersion: "" }) }),
      params,
      context: await contextFor(env),
    } as never);
    expect(written).toMatchObject({ intent: "write", outcome: { ok: false, reason: "refused", message: "The site's equipment entries are edited in the site's repository, not through Carrel." } });
    expect(await site.adapter.content.get("equipment.heat-block")).toBeNull();
  });
});

test/ai-routes.test.ts.source:
// The browser's side of AI work: the unpublish page the email links to, the AI draft page, and
// flags in the editor. Driven through loaders and actions with a real request context.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { addFinding, saveAiDraft } from "~/lib/ai.server";
import { readDraft } from "~/lib/content.server";
import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { requireSiteProject } from "~/lib/projects.server";
import { action as aiDraftAction, loader as aiDraftLoader } from "~/routes/ai-draft";
import { action as editorAction, loader as editorLoader } from "~/routes/editor";
import { action as unpublishAction, loader as unpublishLoader } from "~/routes/unpublish";

import { addPerson, addProject, resetDb, share, testEnv } from "./env";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const SLUG = "de-info";
let site: ReturnType<typeof fakeSite>;
let env: Env;

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  const id = await addProject(SLUG, "dustinedwards");
  await share(id, editor, "editor");
  site = fakeSite();
  // The routes call the site through the global fetch, as the Worker does.
  vi.stubGlobal("fetch", site.fetch);
  env = connectedEnv();
});

async function context(email: string) {
  const c = new RouterContextProvider();
  c.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
  c.set(viewerContext, await viewerFor(email));
  c.set(nonceContext, "n");
  return c;
}

async function settle<T>(p: Promise<T>): Promise<T | Response> {
  try {
    return await p;
  } catch (thrown) {
    if (thrown instanceof Response) return thrown;
    throw thrown;
  }
}

async function published() {
  const saved = await site.adapter.content.saveDraft("post-one", { source: "---\ntitle: Post one\n---\nWords.\n", expectedVersion: null, changeId: "s" });
  await site.adapter.content.publish("post-one", { expectedVersion: saved.version, changeId: "p" });
}

async function as(email: string) {
  const viewer = await viewerFor(email);
  return { viewer, project: await requireSiteProject(testEnv.DB, viewer, SLUG, "read") };
}

describe("the unpublish page", () => {
  it("opens without changing anything, and one button returns the post to draft", async () => {
    await published();
    const params = { project: SLUG, item: "post-one" };
    const page = (await unpublishLoader({ request: new Request("https://carrel.test/"), params, context: await context("owner@test.invalid") } as never)) as Awaited<
      ReturnType<typeof unpublishLoader>
    >;
    expect(page.item).toMatchObject({ title: "Post one", status: "published" });
    expect((await site.adapter.content.get("post-one"))?.status).toBe("published");

    const done = await unpublishAction({ request: new Request("https://carrel.test/", { method: "POST" }), params, context: await context("owner@test.invalid") } as never);
    expect(done).toMatchObject({ ok: true, message: "Returned to draft. It is off the site." });
    expect((await site.adapter.content.get("post-one"))?.status).toBe("draft");
  });

  it("PLANT: an Editor cannot open it or use it", async () => {
    await published();
    const params = { project: SLUG, item: "post-one" };
    expect(((await settle(unpublishLoader({ request: new Request("https://carrel.test/"), params, context: await context("editor@test.invalid") } as never))) as Response).status).toBe(403);
    expect(
      ((await settle(unpublishAction({ request: new Request("https://carrel.test/", { method: "POST" }), params, context: await context("editor@test.invalid") } as never))) as Response).status,
    ).toBe(403);
    expect((await site.adapter.content.get("post-one"))?.status).toBe("published");
  });
});

describe("AI drafts in the browser", () => {
  it("shows an AI draft to the person whose session saved it, and Use as my draft replaces only their working copy", async () => {
    await published();
    const { viewer, project } = await as("owner@test.invalid");
    const saved = await saveAiDraft(env, project, { viewer, client: "Claude 1.0" }, "post-one", { source: "AI text.", note: "A note." }, site.fetch);
    const params = { project: SLUG, item: "post-one", id: String(saved.id) };
    const page = (await aiDraftLoader({ request: new Request("https://carrel.test/"), params, context: await context("owner@test.invalid") } as never)) as Awaited<ReturnType<typeof aiDraftLoader>>;
    expect(page.draft).toMatchObject({ client: "Claude 1.0", note: "A note.", source: "AI text." });

    const used = (await aiDraftAction({ request: new Request("https://carrel.test/", { method: "POST" }), params, context: await context("owner@test.invalid") } as never)) as Response;
    expect(used.headers.get("Location")).toBe(`/p/${SLUG}/e/post-one`);
    expect((await readDraft(testEnv.DB, project, viewer, "post-one"))?.source).toBe("AI text.");
    expect((await site.adapter.content.get("post-one"))?.source).toBe("---\ntitle: Post one\n---\nWords.\n");
  });

  it("PLANT: another person cannot see someone's AI draft", async () => {
    const { viewer, project } = await as("owner@test.invalid");
    const saved = await saveAiDraft(env, project, { viewer, client: "Claude" }, "post-one", { source: "Private." }, site.fetch);
    const params = { project: SLUG, item: "post-one", id: String(saved.id) };
    expect(((await settle(aiDraftLoader({ request: new Request("https://carrel.test/"), params, context: await context("editor@test.invalid") } as never))) as Response).status).toBe(404);
  });
});

describe("flags in the editor", () => {
  it("lists flags, and only the Owner dismisses one", async () => {
    await published();
    const reviewer = await viewerFor("owner@test.invalid");
    const { project } = await as("owner@test.invalid");
    const flag = await addFinding(testEnv.DB, project, { viewer: { ...reviewer, isReviewer: true }, client: "Grok Build" }, "post-one", { message: "Check this." });
    const params = { project: SLUG, item: "post-one" };
    const data = (await editorLoader({ request: new Request("https://carrel.test/"), params, context: await context("editor@test.invalid") } as never)) as Awaited<ReturnType<typeof editorLoader>>;
    expect(data.flags).toMatchObject([{ status: "open", message: "Check this. (from Grok Build)" }]);

    const dismiss = (email: string) => {
      const body = new FormData();
      body.set("intent", "dismiss-flag");
      body.set("flag", String(flag.id));
      return context(email).then((c) => settle(editorAction({ request: new Request("https://carrel.test/", { method: "POST", body }), params, context: c } as never)));
    };
    expect(((await dismiss("editor@test.invalid")) as Response).status).toBe(403);
    expect(await dismiss("owner@test.invalid")).toEqual({ intent: "dismiss-flag", dismissed: flag.id });
  });
});

test/editor-ux.test.ts.source:
// The editor and AI draft screens' behaviour behind the UX pass: "Use as my draft" writes the
// person's working copy in Carrel and nothing to the site, the AI draft's rendered view is private
// to its owner, and the save line says a draft on the site is not live.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { saveAiDraft } from "~/lib/ai.server";
import { readDraft } from "~/lib/content.server";
import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { requireSiteProject } from "~/lib/projects.server";
import { siteState } from "~/lib/save-state";
import { action as aiDraftAction } from "~/routes/ai-draft";
import { loader as aiPreviewLoader } from "~/routes/ai-draft.preview";

import { addPerson, addProject, resetDb, share } from "./env";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const SLUG = "de-info";
const THEIR_SOURCE = "---\ntitle: The AI's take\nunknown_key: kept\n---\nAn alternative opening.\n";
let site: ReturnType<typeof fakeSite>;
let env: Env;

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  const id = await addProject(SLUG, "dustinedwards");
  await share(id, editor, "editor");
  site = fakeSite();
  vi.stubGlobal("fetch", site.fetch);
  env = connectedEnv();
});

async function context(email: string) {
  const c = new RouterContextProvider();
  c.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
  c.set(viewerContext, await viewerFor(email));
  c.set(nonceContext, "n");
  return c;
}

async function aiDraftFor(email: string, item: string) {
  const viewer = await viewerFor(email);
  const project = await requireSiteProject(env.DB, viewer, SLUG, "edit");
  const { id } = await saveAiDraft(env, project, { viewer, client: "Claude" }, item, { source: THEIR_SOURCE });
  return { id, viewer, project };
}

describe("Use as my draft", () => {
  it("writes the working copy in Carrel exactly as the AI wrote it, and sends nothing to the site", async () => {
    const saved = await site.adapter.content.saveDraft("post-one", { source: "---\ntitle: Site copy\n---\nOn the site.\n", expectedVersion: null, changeId: "s" });
    const { id, viewer, project } = await aiDraftFor("owner@test.invalid", "post-one");
    const before = site.requests.length;

    const result = await aiDraftAction({ params: { project: SLUG, item: "post-one", id: String(id) }, request: new Request("https://carrel.test/", { method: "POST" }), context: await context("owner@test.invalid") } as never);
    expect((result as Response).status).toBe(302);

    expect(await readDraft(env.DB, project, viewer, "post-one")).toMatchObject({ source: THEIR_SOURCE });
    expect(site.requests.slice(before).filter((r) => !r.startsWith("GET "))).toEqual([]);
    const onSite = await site.adapter.content.get("post-one");
    expect(onSite?.version).toBe(saved.version);
    expect(onSite?.source).toContain("On the site.");
  });
});

describe("the AI draft's rendered view", () => {
  it("renders the draft through the site for its owner", async () => {
    const { id } = await aiDraftFor("owner@test.invalid", "post-one");
    const response = (await aiPreviewLoader({ params: { project: SLUG, item: "post-one", id: String(id) }, context: await context("owner@test.invalid") } as never)) as Response;
    expect(response.status).toBe(200);
    expect(response.headers.get("Content-Security-Policy")).toMatch(/^sandbox; default-src 'none'/);
    expect(await response.text()).toContain("The AI's take");
  });

  it("PLANT: is never shown to another person, whose request answers 404", async () => {
    const { id } = await aiDraftFor("owner@test.invalid", "post-one");
    await expect(aiPreviewLoader({ params: { project: SLUG, item: "post-one", id: String(id) }, context: await context("editor@test.invalid") } as never)).rejects.toMatchObject({ status: 404 });
  });
});

describe("the save line", () => {
  it("does not read as live for a draft on the site", () => {
    expect(siteState("draft", false)).toBe("Saved as a draft on the site. Not published yet.");
    expect(siteState("draft", true)).toBe("Matches the site's draft. It is not live.");
    expect(siteState("scheduled", true)).toMatch(/scheduled/);
    expect(siteState("published", true)).toBe("Matches the live post");
  });
});

test/export.test.ts.source:
// Export (ePub, Word, the print page for PDF) and the two small parsers under it: scene headers and
// the prose Markdown scenes use. The files are opened again here, not just produced.

import { strFromU8, unzipSync } from "fflate";
import { describe, expect, it } from "vitest";

import type { Assembled } from "~/lib/books.server";
import { buildDocx, buildEpub, parseInline, parseProse, printHtml } from "~/lib/novels/export";
import { list, parseFile, text } from "~/lib/novels/frontmatter";
import { isBookPath, nextNumbered, slugify, titleFromSegment } from "~/lib/novels/layout";

const BOOK: Assembled = {
  title: "The Test Book & Co.",
  author: "Test Author",
  language: "en",
  chapters: [
    { slug: "01-arrival", title: "Arrival", scenes: [{ path: "a", body: "Wade opened the *old* gate.\n\nHe said <nothing>." }, { path: "b", body: "Supper, **late**." }] },
    { slug: "02-letters", title: "Letters", scenes: [{ path: "c", body: "> A letter, read aloud.\n\nThe end." }] },
  ],
};

describe("scene headers", () => {
  it("reads strings, inline lists, dash lists, booleans and quotes, and reports what it cannot read", () => {
    const parsed = parseFile(
      "---\npov: Wade\ncharacters: [Wade, \"Harlan, June\"]\naliases:\n  - Mrs. Harlan\n  - June\nflashback: true\ngoal:\n# a comment\nnonsense here\n---\n\nBody line.\n",
    );
    expect(parsed.data).toEqual({ pov: "Wade", characters: ["Wade", "Harlan, June"], aliases: ["Mrs. Harlan", "June"], flashback: true, goal: "" });
    expect(parsed.problems).toEqual([{ line: 10, text: "nonsense here" }]);
    expect(parsed.bodyLine).toBe(12);
    expect(parsed.body).toBe("\nBody line.\n");
    expect(list(parsed.data, "characters")).toEqual(["Wade", "Harlan, June"]);
    expect(text(parsed.data, "goal")).toBe("");
  });

  it("treats a file with no header, or an unclosed one, as all body", () => {
    expect(parseFile("Just prose.\n")).toMatchObject({ data: {}, bodyLine: 1 });
    expect(parseFile("---\npov: x\n").problems).toHaveLength(1);
  });
});

describe("the layout", () => {
  it("allows the novels layout and nothing else", () => {
    for (const ok of ["book.md", "chapters/01-arrival/01-the-gate.md", "chapters/100-late/12-end.md", "bible/characters/wade.md", "bible/world.md", "outline/plan.md"]) {
      expect(isBookPath(ok), ok).toBe(true);
    }
    for (const bad of ["../x.md", "build/x.md", "chapters/arrival/01-a.md", "chapters/01-a/b.md", "bible/other/x.md", "notes.md", "Book.md", "chapters/01-a/01-b.txt", "outline/a/b.md"]) {
      expect(isBookPath(bad), bad).toBe(false);
    }
  });

  it("names and numbers chapters and scenes", () => {
    expect(titleFromSegment("03-the-long-road")).toBe("The long road");
    expect(slugify("The Crossing, Part II!")).toBe("the-crossing-part-ii");
    expect(slugify("Río Café")).toBe("rio-cafe");
    expect(nextNumbered(["01-a", "02-b", "09-c"], "d")).toBe("10-d");
    expect(nextNumbered([], "first")).toBe("01-first");
  });
});

describe("prose Markdown", () => {
  it("parses emphasis and strong, and leaves unmatched markers and snake_case as text", () => {
    expect(parseInline("a *b* **c** _d_")).toEqual([
      { text: "a ", em: false, strong: false },
      { text: "b", em: true, strong: false },
      { text: " ", em: false, strong: false },
      { text: "c", em: false, strong: true },
      { text: " ", em: false, strong: false },
      { text: "d", em: true, strong: false },
    ]);
    expect(parseInline("2 * 3 and snake_case_name")).toEqual([{ text: "2 * 3 and snake_case_name", em: false, strong: false }]);
    expect(parseInline("\\*literal\\*")).toEqual([{ text: "*literal*", em: false, strong: false }]);
  });

  it("splits paragraphs, scene breaks, headings and quotes; joins hard-wrapped lines", () => {
    expect(parseProse("One\ntwo.\n\n* * *\n\n## Part\n\n> q1\n> q2").map((b) => b.type)).toEqual(["p", "break", "h", "quote"]);
    expect(parseProse("One\ntwo.")[0]).toEqual({ type: "p", inlines: [{ text: "One two.", em: false, strong: false }] });
  });
});

describe("ePub", () => {
  const files = unzipSync(buildEpub(BOOK, { id: "0f0e7c2a-6a8b-4d1e-9d5e-3a4b5c6d7e8f", modified: new Date("2026-09-27T03:00:00.123Z") }));

  it("puts an uncompressed mimetype first, as the container format requires", () => {
    const zip = buildEpub(BOOK, { id: "x", modified: new Date() });
    // Local file header: signature, then compression method at offset 8 (0 = stored), name at 30.
    expect([...zip.slice(0, 4)]).toEqual([0x50, 0x4b, 0x03, 0x04]);
    expect(zip[8]).toBe(0);
    expect(strFromU8(zip.slice(30, 38))).toBe("mimetype");
    expect(strFromU8(files["mimetype"]!)).toBe("application/epub+zip");
  });

  it("has a package document, a navigation document and one XHTML file per chapter, escaped", () => {
    expect(Object.keys(files).sort()).toEqual([
      "META-INF/container.xml",
      "OEBPS/book.css",
      "OEBPS/chapter-001.xhtml",
      "OEBPS/chapter-002.xhtml",
      "OEBPS/content.opf",
      "OEBPS/nav.xhtml",
      "OEBPS/title.xhtml",
      "mimetype",
    ]);
    const opf = strFromU8(files["OEBPS/content.opf"]!);
    expect(opf).toContain("<dc:title>The Test Book &amp; Co.</dc:title>");
    expect(opf).toContain('<meta property="dcterms:modified">2026-09-27T03:00:00Z</meta>');
    expect(opf).toContain('<itemref idref="c2"/>');
    const one = strFromU8(files["OEBPS/chapter-001.xhtml"]!);
    expect(one).toContain("<h1>Arrival</h1>");
    expect(one).toContain("<p>Wade opened the <em>old</em> gate.</p>");
    expect(one).toContain("He said &lt;nothing&gt;.");
    expect(one).toContain('<p class="scene-break">* * *</p>\n<p>Supper, <strong>late</strong>.</p>');
    expect(strFromU8(files["OEBPS/chapter-002.xhtml"]!)).toContain("<blockquote><p>A letter, read aloud.</p></blockquote>");
    expect(strFromU8(files["OEBPS/nav.xhtml"]!)).toContain('<a href="chapter-002.xhtml">Letters</a>');
  });
});

describe("Word", () => {
  it("is a Word document holding the title, each chapter and the formatting", async () => {
    const files = unzipSync(new Uint8Array(await buildDocx(BOOK)));
    const xml = strFromU8(files["word/document.xml"]!);
    for (const t of ["The Test Book &amp; Co.", "Arrival", "Letters", "Wade opened the ", "old", "* * *", "late"]) expect(xml).toContain(t);
    // The emphasis survives as italics on its own run.
    expect(xml).toMatch(/<w:i\/>[\s\S]*?<w:t[^>]*>old<\/w:t>/);
  });
});

describe("the print page", () => {
  it("is the whole book with each chapter on a new page, escaped", () => {
    const html = printHtml(BOOK);
    expect(html).toContain("<title>The Test Book &amp; Co.</title>");
    expect(html).toContain(".chapter { break-before: page; }");
    expect(html.match(/<section class="chapter">/g)).toHaveLength(2);
    expect(html).not.toContain("<nothing>");
  });
});

test/books.test.ts.source:
// Books through Carrel's service layer, against the fake novels repository: who may open, save and
// export; a save that commits with the version it expects and records who wrote what; the checks
// that run on save and never stop it; and export held while a flag is open.

import { beforeEach, describe, expect, it } from "vitest";

import {
  assembleBook,
  authorshipRecord,
  authorshipReport,
  checkDraft,
  createBook,
  dismissFinding,
  exportGate,
  listFiles,
  listFindings,
  refreshBook,
  requireBookProject,
  saveBookFile,
  wordDelta,
} from "~/lib/books.server";
import { autosave, readDraft } from "~/lib/content.server";
import { requireSiteProject } from "~/lib/projects.server";

import { addBook, addPerson, addProject, resetDb, share, testEnv } from "./env";
import { BASELINE, PLANT } from "./fixtures/voice";
import { fakeNovels } from "./novels";
import { viewerFor } from "./site";

const SLUG = "test-book";

const WADE = "---\nname: Wade Pruitt\naliases: [Wade]\nborn: 1996-02-11\n---\nRanch hand.\n";
const PLACE = "---\nname: Harlan place\n---\n";
const RULE = "---\nname: No phones past the ridge\nforbidden: [phone rang]\n---\n";
const HEADER = "---\npov: Wade\ndate: 2024-04-12\nlocation: Harlan place\ncharacters: [Wade]\ngoal: get in\nconflict: the lock\noutcome: he opens it\n---\n\n";

function seedRepo(extra: Record<string, string> = {}) {
  return fakeNovels({
    [`${SLUG}/book.md`]: "---\ntitle: The Test Book\nauthor: Test Author\n---\n",
    [`${SLUG}/bible/characters/wade.md`]: WADE,
    [`${SLUG}/bible/places/harlan-place.md`]: PLACE,
    [`${SLUG}/bible/rules/phones.md`]: RULE,
    [`${SLUG}/chapters/01-arrival/01-the-gate.md`]: `${HEADER}Wade opened the gate.\n`,
    [`${SLUG}/chapters/01-arrival/02-supper.md`]: HEADER.replace("2024-04-12", "2024-04-12 19:00") + "They ate at the kitchen table.\n",
    [`${SLUG}/outline/plan.md`]: "# Plan\n",
    [`${SLUG}/build/book.epub`]: "ignored",
    [`${SLUG}/notes.txt`]: "ignored",
    "shared/checks/ai-habits.md": "---\nwords: [suddenly]\n---\n",
    ...extra,
  });
}

async function refusal(promise: Promise<unknown>): Promise<number> {
  try {
    await promise;
  } catch (thrown) {
    if (thrown instanceof Response) return thrown.status;
    throw thrown;
  }
  throw new Error("expected a refusal, and the call succeeded");
}

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  const reader = await addPerson("reader@test.invalid");
  await addPerson("stranger@test.invalid");
  const id = await addBook(SLUG);
  await share(id, editor, "editor");
  await share(id, reader, "reader");
});

async function as(email: string, action: "read" | "edit" | "publish" = "read") {
  const viewer = await viewerFor(email);
  return { viewer, project: await requireBookProject(testEnv.DB, viewer, SLUG, action) };
}

describe("opening a book", () => {
  it("PLANT: a non-member, a missing book, and a site all answer 404", async () => {
    const stranger = await viewerFor("stranger@test.invalid");
    const owner = await viewerFor("owner@test.invalid");
    await addProject("a-site", "dustinedwards");
    expect(await refusal(requireBookProject(testEnv.DB, stranger, SLUG, "read"))).toBe(404);
    expect(await refusal(requireBookProject(testEnv.DB, owner, "no-such-book", "read"))).toBe(404);
    expect(await refusal(requireBookProject(testEnv.DB, owner, "a-site", "read"))).toBe(404);
    // And the other way: a book is not a site.
    expect(await refusal(requireSiteProject(testEnv.DB, owner, SLUG, "read"))).toBe(404);
  });

  it("PLANT: a Reader asking to edit is refused 403", async () => {
    const reader = await viewerFor("reader@test.invalid");
    expect(await refusal(requireBookProject(testEnv.DB, reader, SLUG, "edit"))).toBe(403);
  });

  it("creates a book for the Owner only, with a folder name the layout allows", async () => {
    const owner = await viewerFor("owner@test.invalid");
    const editor = await viewerFor("editor@test.invalid");
    expect(await refusal(createBook(testEnv.DB, editor, { name: "Mine", folder: "mine" }))).toBe(403);
    expect(await createBook(testEnv.DB, owner, { name: "Paluxy Portal", folder: "paluxy-portal" })).toEqual({ ok: true, slug: "paluxy-portal" });
    expect((await createBook(testEnv.DB, owner, { name: "Again", folder: "paluxy-portal" })).ok).toBe(false);
    expect((await createBook(testEnv.DB, owner, { name: "Bad", folder: "../etc" })).ok).toBe(false);
    expect((await createBook(testEnv.DB, owner, { name: "Shared", folder: "shared" })).ok).toBe(false);
  });
});

describe("refresh from Git", () => {
  it("indexes the book's Markdown files by kind, skips build/ and other files, and reads shared/", async () => {
    const gh = seedRepo();
    const { project } = await as("reader@test.invalid");
    const result = await refreshBook(testEnv.DB, gh.repo, project);
    expect(result).toMatchObject({ files: 7, read: 7, removed: 0, shared: 1, more: false });
    const files = await listFiles(testEnv.DB, project);
    expect(files.map((f) => [f.path, f.kind])).toEqual([
      ["bible/characters/wade.md", "character"],
      ["bible/places/harlan-place.md", "place"],
      ["bible/rules/phones.md", "rule"],
      ["book.md", "book"],
      ["chapters/01-arrival/01-the-gate.md", "scene"],
      ["chapters/01-arrival/02-supper.md", "scene"],
      ["outline/plan.md", "outline"],
    ]);
    // A clean book has nothing flagged.
    expect(await listFindings(testEnv.DB, project)).toEqual([]);
  });

  it("reads again only what changed, and drops what Git no longer has", async () => {
    const gh = seedRepo();
    const { project } = await as("reader@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, project);
    gh.files.delete(`${SLUG}/outline/plan.md`);
    await gh.commitElsewhere(`${SLUG}/chapters/01-arrival/02-supper.md`, `${HEADER}Suddenly they ate.\n`);
    const before = gh.requests.length;
    expect(await refreshBook(testEnv.DB, gh.repo, project)).toMatchObject({ read: 1, removed: 1, shared: 0 });
    expect(gh.requests.slice(before).filter((r) => r.includes("/contents/"))).toEqual([
      `GET /repos/DrDustinEdwards/novels/contents/${SLUG}/chapters/01-arrival/02-supper.md`,
    ]);
    // The checks ran on what changed outside Carrel, with the book's own habits list.
    expect((await listFindings(testEnv.DB, project)).map((f) => f.excerpt)).toEqual(["Suddenly"]);
  });
});

describe("saving", () => {
  it("PLANT: a Reader cannot autosave or save, and Git hears nothing", async () => {
    const gh = seedRepo();
    const { viewer, project } = await as("reader@test.invalid");
    const path = "chapters/01-arrival/01-the-gate.md";
    expect(await refusal(autosave(testEnv.DB, project, viewer, path, { source: "x", baseVersion: null }))).toBe(403);
    expect(await refusal(saveBookFile(testEnv.DB, gh.repo, project, viewer, path, { source: "x", expectedVersion: null }))).toBe(403);
    expect(gh.requests.filter((r) => r.startsWith("PUT"))).toEqual([]);
  });

  it("PLANT: a path outside the layout is refused before Git is asked", async () => {
    const gh = seedRepo();
    const { viewer, project } = await as("owner@test.invalid");
    for (const path of ["../other-book/book.md", "build/x.md", "chapters/one/two.md", "notes.txt", "chapters/01-a/01-b.md/../../x.md"]) {
      expect(await refusal(saveBookFile(testEnv.DB, gh.repo, project, viewer, path, { source: "x", expectedVersion: null }))).toBe(404);
    }
    expect(gh.requests).toEqual([]);
  });

  it("commits as the person with a change id and no AI trailer, records authorship, clears the draft", async () => {
    const gh = seedRepo();
    const { viewer, project } = await as("editor@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, project);
    const path = "chapters/01-arrival/01-the-gate.md";
    const file = (await listFiles(testEnv.DB, project)).find((f) => f.path === path)!;
    await autosave(testEnv.DB, project, viewer, path, { source: "draft", baseVersion: file.sha });

    const result = await saveBookFile(testEnv.DB, gh.repo, project, viewer, path, {
      source: `${HEADER}Wade opened the old gate slowly.\n`,
      expectedVersion: file.sha,
    });
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(gh.commits).toHaveLength(1);
    expect(gh.commits[0]).toMatchObject({ path: `${SLUG}/${path}`, author: { name: "editor", email: "editor@test.invalid" } });
    expect(gh.commits[0]!.message).toBe(`Save ${SLUG}/${path}\n\nCarrel-Change: ${result.changeId}`);
    expect(gh.commits[0]!.message).not.toMatch(/claude|anthropic|co-authored/i);
    expect(await readDraft(testEnv.DB, project, viewer, path)).toBeNull();

    const record = await authorshipRecord(testEnv.DB, project);
    expect(record).toMatchObject([{ id: result.changeId, path, who: "editor", client: null, wordsAdded: 2, wordsRemoved: 0, commit: result.commit }]);
    const report = authorshipReport(project, record, new Date("2026-09-27T00:00:00Z"));
    expect(report).toContain("| editor | 1 | 2 | 0 |");
    expect(report).toContain(`| editor | ${path} | 2 | 0 | ${result.commit.slice(0, 7)} |`);
  });

  it("PLANT: a stale expected version is refused as a conflict, and the draft is kept", async () => {
    const gh = seedRepo();
    const { viewer, project } = await as("owner@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, project);
    const path = "chapters/01-arrival/01-the-gate.md";
    const opened = (await listFiles(testEnv.DB, project)).find((f) => f.path === path)!.sha;
    await autosave(testEnv.DB, project, viewer, path, { source: "my words", baseVersion: opened });
    await gh.commitElsewhere(`${SLUG}/${path}`, `${HEADER}Someone else's words.\n`);

    const result = await saveBookFile(testEnv.DB, gh.repo, project, viewer, path, { source: "my words", expectedVersion: opened });
    expect(result).toMatchObject({ ok: false, reason: "conflict" });
    expect(gh.files.get(`${SLUG}/${path}`)!.source).toBe(`${HEADER}Someone else's words.\n`);
    expect((await readDraft(testEnv.DB, project, viewer, path))?.source).toBe("my words");
    expect(await authorshipRecord(testEnv.DB, project)).toEqual([]);
  });

  it("creates a new scene only where no file exists", async () => {
    const gh = seedRepo();
    const { viewer, project } = await as("owner@test.invalid");
    const path = "chapters/02-letters/01-morning.md";
    const created = await saveBookFile(testEnv.DB, gh.repo, project, viewer, path, { source: `${HEADER.replace("2024-04-12", "2024-04-13")}Morning.\n`, expectedVersion: null });
    expect(created.ok).toBe(true);
    const again = await saveBookFile(testEnv.DB, gh.repo, project, viewer, path, { source: "overwrite", expectedVersion: null });
    expect(again).toMatchObject({ ok: false, reason: "conflict" });
  });
});

describe("checks on save", () => {
  it("PLANT: a flagged scene still saves; the flags come back and are recorded", async () => {
    const gh = seedRepo();
    const { viewer, project } = await as("owner@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, project);
    const path = "chapters/01-arrival/03-late.md";
    const source = HEADER.replace("characters: [Wade]", "characters: [Wade, Tobias]").replace("2024-04-12", "2024-04-11") + "Then the phone rang. It's not just a farm, it's a promise.\n";
    const result = await saveBookFile(testEnv.DB, gh.repo, project, viewer, path, { source, expectedVersion: null });
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(gh.files.get(`${SLUG}/${path}`)!.source).toBe(source);
    expect(result.findings.map((f) => f.check).sort()).toEqual(["ai-habits", "continuity", "timeline", "world-rules"]);
    expect((await listFindings(testEnv.DB, project, { path })).map((f) => f.check).sort()).toEqual(["ai-habits", "continuity", "timeline", "world-rules"]);
  });

  it("PLANT: the voice check flags another author's passage once shared/voice/ holds Dustin's", async () => {
    const voice = Object.fromEntries(BASELINE.map((text, i) => [`shared/voice/passage-${i + 1}.md`, text]));
    const gh = seedRepo({ ...voice, "shared/voice/README.md": "Put your passages here." });
    const { viewer, project } = await as("owner@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, project);
    const result = await saveBookFile(testEnv.DB, gh.repo, project, viewer, "chapters/01-arrival/03-tea.md", {
      source: HEADER.replace("2024-04-12", "2024-04-13") + PLANT,
      expectedVersion: null,
    });
    expect(result.ok && result.findings.map((f) => f.check)).toEqual(["voice"]);
  });

  it("fixing the text clears the flag; saving a bible entry rechecks every scene", async () => {
    const gh = seedRepo();
    const { viewer, project } = await as("owner@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, project);
    const path = "chapters/01-arrival/03-late.md";
    const withTobias = HEADER.replace("characters: [Wade]", "characters: [Wade, Tobias]").replace("2024-04-12", "2024-04-13") + "Quiet.\n";
    const saved = await saveBookFile(testEnv.DB, gh.repo, project, viewer, path, { source: withTobias, expectedVersion: null });
    expect((await listFindings(testEnv.DB, project, { status: "open" })).map((f) => f.excerpt)).toEqual(["Tobias"]);

    // Adding Tobias to the bible resolves the scene's flag without touching the scene.
    const bible = await saveBookFile(testEnv.DB, gh.repo, project, viewer, "bible/characters/tobias.md", { source: "---\nname: Tobias\n---\n", expectedVersion: null });
    expect(bible.ok && saved.ok).toBe(true);
    expect(await listFindings(testEnv.DB, project)).toEqual([]);
  });

  it("checks a draft without saving or recording anything", async () => {
    const gh = seedRepo();
    const { project } = await as("reader@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, project);
    const found = await checkDraft(testEnv.DB, project, "chapters/01-arrival/01-the-gate.md", `${HEADER}A tapestry.\n`);
    expect(found.map((f) => f.excerpt)).toEqual(["tapestry"]);
    expect(await listFindings(testEnv.DB, project)).toEqual([]);
    expect(gh.requests.filter((r) => r.startsWith("PUT"))).toEqual([]);
  });
});

describe("dismissing flags and exporting", () => {
  async function flagged() {
    const gh = seedRepo();
    const owner = await as("owner@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, owner.project);
    await saveBookFile(testEnv.DB, gh.repo, owner.project, owner.viewer, "chapters/01-arrival/03-late.md", {
      source: HEADER.replace("2024-04-12", "2024-04-13") + "A tapestry. Another tapestry.\n",
      expectedVersion: null,
    });
    return { gh, owner };
  }

  it("PLANT: export is refused while a flag is open, and to anyone but the Owner", async () => {
    const { owner } = await flagged();
    expect(await exportGate(testEnv.DB, owner.project)).toMatchObject({ ok: false, open: 2 });
    const editor = await as("editor@test.invalid");
    expect(await refusal(exportGate(testEnv.DB, editor.project))).toBe(403);
    expect(await refusal(assembleBook(testEnv.DB, editor.project, editor.viewer))).toBe(403);
  });

  it("PLANT: an Editor cannot dismiss a flag; the Owner can, and a dismissal survives the next save", async () => {
    const { gh, owner } = await flagged();
    const editor = await as("editor@test.invalid");
    const [first, second] = await listFindings(testEnv.DB, owner.project);
    expect(await refusal(dismissFinding(testEnv.DB, editor.project, editor.viewer, first!.id))).toBe(403);

    await dismissFinding(testEnv.DB, owner.project, owner.viewer, first!.id);
    await dismissFinding(testEnv.DB, owner.project, owner.viewer, second!.id);
    expect(await exportGate(testEnv.DB, owner.project)).toEqual({ ok: true });

    // Saving again with the same words keeps both dismissed; a new tapestry is a new flag.
    const path = "chapters/01-arrival/03-late.md";
    const current = gh.files.get(`${SLUG}/${path}`)!;
    await saveBookFile(testEnv.DB, gh.repo, owner.project, owner.viewer, path, { source: `${current.source}A third tapestry.\n`, expectedVersion: current.sha });
    const all = await listFindings(testEnv.DB, owner.project);
    expect(all.map((f) => f.status).sort()).toEqual(["dismissed", "dismissed", "open"]);
  });

  it("a dismissal in another book cannot be reached by id", async () => {
    const { owner } = await flagged();
    const [finding] = await listFindings(testEnv.DB, owner.project);
    await addBook("other-book");
    const other = await requireBookProject(testEnv.DB, owner.viewer, "other-book", "publish");
    expect(await refusal(dismissFinding(testEnv.DB, other, owner.viewer, finding!.id))).toBe(404);
  });

  it("assembles the book in reading order with its title and author from book.md", async () => {
    const gh = seedRepo({ [`${SLUG}/chapters/10-late/01-end.md`]: `${HEADER.replace("2024-04-12", "2024-05-01")}The end.\n` });
    const { viewer, project } = await as("owner@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, project);
    const book = await assembleBook(testEnv.DB, project, viewer);
    expect(book.title).toBe("The Test Book");
    expect(book.author).toBe("Test Author");
    expect(book.chapters.map((c) => [c.title, c.scenes.map((s) => s.body)])).toEqual([
      ["Arrival", ["Wade opened the gate.", "They ate at the kitchen table."]],
      ["Late", ["The end."]],
    ]);
  });
});

describe("word counts for the authorship record", () => {
  it("counts a changed word once each way and a moved word not at all", () => {
    expect(wordDelta("the cat sat", "the dog sat")).toEqual({ added: 1, removed: 1 });
    expect(wordDelta("a b c", "c b a")).toEqual({ added: 0, removed: 0 });
    expect(wordDelta(null, "---\ntitle: x\n---\none two")).toEqual({ added: 2, removed: 0 });
  });
});

